window.DISHES = [
{id:"aligot",group:"france",name:{en:"Aligot",fr:"Aligot"},
region:{en:"Aubrac, Aveyron and Lozère",fr:"Aubrac, Aveyron et Lozère"},era:{en:"Pilgrim food from the twelfth century; potato replaced bread in the eighteenth",fr:"Nourriture de pèlerins depuis le XIIe siècle ; la pomme de terre a remplacé le pain au XVIIIe"},
summary:{en:"A potato purée beaten with fresh Aubrac curd until it pulls into long elastic ribbons. It is eaten on its own or under a sausage, and it is judged on nothing but how far it stretches.",
fr:"Purée de pomme de terre travaillée avec de la tome fraîche de l'Aubrac jusqu'à filer en longs rubans élastiques. On le sert seul ou sous une saucisse, et on le juge à sa seule capacité à filer."},
balance:{en:"Aligot is an emulsion of starch and fat held together by cheese protein. The purée has to be worked very hot so the melted curd stretches into long threads: too cold and it tightens into rubber, too hot and the fat separates out. Butter and cream carry the flavour and keep the mass fluid, and raw garlic gives the only sharp note against a base that is very rich and very mild. Salt does the rest of the balancing work, because young curd brings almost no acidity of its own.",
fr:"L'aligot est une émulsion d'amidon et de matière grasse tenue par la protéine du fromage. La purée doit être travaillée très chaude pour que le caillé fondu s'étire en longs fils : trop froid il se resserre en caoutchouc, trop chaud le gras se sépare. Le beurre et la crème apportent le goût et maintiennent la masse fluide, et l'ail cru donne la seule note vive contre une base très grasse et très douce. Le sel fait le reste du travail d'équilibre, car la tome jeune n'apporte presque aucune acidité."},
ingredients:["bintje-potato","laguiole","cantal","butter","creme-fraiche","garlic","salt"],
techniques:["bouillir","cremer","monter-au-beurre","mijoter"],
wines:[{appellation:"Marcillac (Aveyron, fer servadou)",style:"dry red, medium tannin, red fruit and iron notes",band:2,why:{en:"Tannin binds the fat of the melted cheese and clears the palate between spoonfuls.",fr:"Le tanin se lie au gras du fromage fondu et nettoie le palais entre deux cuillerées."}},{appellation:"Côtes d'Auvergne rouge (gamay)",style:"light red, low tannin, high acidity",band:2,why:{en:"Acidity rather than tannin does the cutting, so the wine is not flattened by the starch.",fr:"C'est l'acidité, et non le tanin, qui coupe ici : le vin n'est pas écrasé par l'amidon."}},{appellation:"Gaillac blanc sec (mauzac)",style:"dry white, green-apple acidity, light body",band:2,why:{en:"Apple acidity offsets the lactic weight of the young curd.",fr:"L'acidité de pomme compense le poids lactique de la tome fraîche."}}]},

{id:"baba-au-rhum",group:"patisserie",name:{en:"Rum baba",fr:"Baba au rhum"},
region:{en:"Lorraine then Paris, rue Montorgueil",fr:"Lorraine puis Paris, rue Montorgueil"},era:{en:"18th century, fixed at Stohrer from 1730; soaked in malaga first, then rum",fr:"XVIIIe siècle, fixé chez Stohrer à partir de 1730 ; imbibage au malaga d’abord, au rhum ensuite"},
summary:{en:"A rich yeast dough, baked dry, then soaked in hot syrup and rum until saturated. It exists because a kouglof was judged too dry and was wetted to fix it.",
fr:"Une pâte levée riche, cuite sèche, puis imbibée de sirop chaud et de rhum jusqu'à saturation. Il existe parce qu'un kouglof jugé trop sec a été mouillé pour le corriger."},
balance:{en:"The dough is deliberately baked hard and left to dry, because a tight, dry crumb has the open gluten structure needed to take up several times its weight in syrup without collapsing. The syrup goes in hot and the baba goes in cold, or the reverse; the temperature difference drives absorption, and soaking is finished when the cake stops rising in the pan. Rum is added off the heat, since alcohol above 78 degrees evaporates and takes the aroma with it. The apricot glaze on the outside seals the surface so the syrup does not run out on the plate, and the unsweetened cream served alongside supplies fat against a cake that is otherwise sugar and alcohol.",
fr:"La pâte est volontairement cuite dure et laissée à sécher, car une mie serrée et sèche possède la structure de gluten ouverte qu'il faut pour absorber plusieurs fois son poids de sirop sans s'effondrer. Le sirop est versé chaud sur un baba froid, ou l'inverse : l'écart de température force l'absorption, et l'imbibage est terminé quand le gâteau cesse de remonter. Le rhum s'ajoute hors du feu, car au-delà de 78 degrés l'alcool s'évapore et emporte l'arôme. Le nappage à l'abricot ferme la surface pour que le sirop ne coule pas à l'assiette, et la crème non sucrée servie à côté apporte le gras face à un gâteau qui n'est sinon que sucre et alcool."},
ingredients:["flour-t45","yeast","egg","butter","sugar","salt","dark-rum","rhum-agricole","vanilla","orange","apricot","cream"],
techniques:["cuisson-du-sucre","pocher","maceration","glacer","dorer"],
wines:[{appellation:"Rhum agricole AOC Martinique, vieux",style:"Sec, 40 à 45 % vol., notes de canne fraîche et de bois",band:2,why:{en:"It repeats the alcohol already present in the soaking syrup, so no second dominant aroma is introduced and the dry spirit cuts the sugar of the syrup.",fr:"Il reprend l'alcool déjà présent dans le sirop d'imbibage : aucun second arôme dominant n'est introduit, et l'alcool sec tranche le sucre du sirop."}},{appellation:"Málaga, pedro ximénez",style:"Vin muté, très sucré, notes de raisin sec et de figue",band:2,why:{en:"Its sugar matches the syrup, and it corresponds to the original soaking liquid, which was Malaga wine before rum replaced it.",fr:"Son sucre est au niveau du sirop, et il correspond au liquide d'imbibage d'origine, le vin de Malaga, avant que le rhum ne le remplace."}},{appellation:"Pineau des Charentes blanc",style:"Moût muté au cognac, sucre élevé, acidité modérée",band:2,why:{en:"The sugar sits at the level of the syrup while the grape-spirit base stays in the same register as the rum instead of competing with it.",fr:"Le sucre se situe au niveau du sirop, et la base d'eau-de-vie de vin reste dans le même registre que le rhum sans le concurrencer."}}]},

{id:"baeckeoffe",group:"france",name:{en:"Baeckeoffe",fr:"Baeckeoffe"},
region:{en:"Alsace",fr:"Alsace"},era:{en:"Descended from the Sabbath hamin; a Monday dish left at the baker's oven",fr:"Descend du hamin du shabbat ; plat du lundi laissé au four du boulanger"},
summary:{en:"Three meats marinated in white wine, layered with potato, leek and onion in a sealed earthenware dish and cooked slowly for hours. The lid is luted with a flour-and-water paste, so nothing escapes.",
fr:"Trois viandes marinées au vin blanc, alternées avec pommes de terre, poireaux et oignons dans une terrine close, et cuites lentement pendant des heures. Le couvercle est luté avec un cordon de farine et d'eau : rien ne s'échappe."},
balance:{en:"The dish is a closed braise: no liquid is added beyond the marinade, so everything that cooks comes from the meats and the potatoes. The potato lining and layers absorb the melted fat and the gelatine released by the three meats, which makes the starch the balancing agent rather than a side dish. The acidity of the marinade and the juniper cut the pork and lamb fat over long hours, while leek and onion collapse into a sweetness that replaces the missing stock. Luting holds the steam in: cooking runs near boiling in a saturated atmosphere, and the meat is never dried out by evaporation.",
fr:"Le plat est un braisage clos : on n'ajoute aucun liquide au-delà de la marinade, si bien que tout ce qui cuit vient des viandes et des pommes de terre. Le chemisage et les couches de pomme de terre absorbent le gras fondu et la gélatine libérée par les trois viandes ; l'amidon est donc l'agent d'équilibre et non un accompagnement. L'acidité de la marinade et le genièvre coupent le gras de porc et d'agneau pendant les longues heures de cuisson, et le poireau et l'oignon s'effondrent en un sucre qui remplace le fond absent. Le lutage retient la vapeur : la cuisson se fait près de l'ébullition dans une atmosphère saturée, et la viande n'est jamais desséchée par l'évaporation."},
ingredients:["echine","epaule-agneau","paleron","bintje-potato","onion","leek","carrot","garlic","juniper","bay-leaf","thyme","parsley","flour-t55"],
techniques:["mariner","emincer","chemiser","braiser","a-l-etouffee"],
wines:[{appellation:"Riesling d'Alsace sec",style:"dry white, high acidity, citrus and mineral",band:2,why:{en:"The acidity cuts the pork and lamb fat rendered into the potato.",fr:"L'acidité coupe le gras de porc et d'agneau rendu dans la pomme de terre."}},{appellation:"Sylvaner d'Alsace",style:"dry white, neutral aroma, moderate acidity",band:1,why:{en:"A neutral profile, because the dish already carries juniper and bay and calls for no added aromatics.",fr:"Un profil neutre, car le plat porte déjà le genièvre et le laurier et n'appelle pas d'arômes supplémentaires."}},{appellation:"Pinot noir d'Alsace",style:"light red, low tannin, red fruit",band:2,why:{en:"Low tannin, so the wine is not hardened by the gelatine of the long braise.",fr:"Peu de tanin, pour que le vin ne soit pas durci par la gélatine du braisage long."}}]},

{id:"blanquette-de-veau",group:"monde",name:{en:"Veal blanquette",fr:"Blanquette de veau"},
region:{en:"No fixed terroir — a bourgeois dish of the French repertoire",fr:"Sans terroir fixe — plat bourgeois du répertoire français"},era:{en:"18th century; first written trace in Vincent La Chapelle, Le Cuisinier moderne, 1735",fr:"XVIIIe siècle ; première trace écrite chez Vincent La Chapelle, Le Cuisinier moderne, 1735"},
summary:{en:"A veal stew cooked with no colouring at all: the meat starts in cold water or white stock and is never browned, and the cooking liquid becomes the sauce. What defines it is the double liaison — a blond roux, then egg yolks and cream added off the heat.",
fr:"Ragoût de veau cuit sans aucune coloration : la viande part à l'eau froide ou au fond blanc, jamais rissolée, et le liquide de cuisson devient la sauce. Ce qui la définit, c'est la double liaison — un roux blond, puis jaunes d'œufs et crème hors du feu."},
balance:{en:"Nothing is browned, so there is no roasted bitterness to work against; the whole construction rests on fat against acid. The yolk-and-cream liaison takes the sauce to a coating consistency and loads it with fat, and the lemon juice added at the end is what keeps it from reading flat. Veal is lean and mild, so the flavour has to be built into the poaching liquid — the meat gives collagen and body, the aromatics give the taste. Rice or steamed potato carries the sauce rather than adding flavour of its own: the starch takes up the excess liquid and slows the palate between mouthfuls.",
fr:"Rien n'est coloré, donc aucune amertume de rôti à contrer : toute la construction repose sur le gras contre l'acide. La liaison aux jaunes et à la crème amène la sauce à la nappe et la charge en gras, et c'est le jus de citron ajouté en fin de cuisson qui l'empêche d'être plate. Le veau est maigre et discret : le goût doit être construit dans le mouillement — la viande donne le collagène et le corps, la garniture aromatique donne le goût. Le riz ou la pomme vapeur porte la sauce sans apporter de goût propre : l'amidon absorbe l'excès de liquide et ralentit le palais entre deux bouchées."},
ingredients:["veau-sous-la-mere","tendron-de-veau","carrot","onion","leek","clove","bay-leaf","mushroom","pearl-onion","butter","flour-t55","cream","egg","lemon"],
techniques:["blanchir","fond-blanc","depouiller","mijoter","roux-blond","veloute","liaison-a-l-oeuf","glacer-a-blanc"],
wines:[{appellation:"Bourgogne, chardonnay",style:"dry, high acidity, little or no oak",band:2,why:{en:"The acidity cuts the cream and the egg-yolk liaison; an unoaked wine leaves the vanilla notes out, which would double up on the fat.",fr:"L'acidité tranche la crème et la liaison aux jaunes ; un vin non boisé écarte les notes vanillées, qui redoubleraient le gras."}},{appellation:"Alsace, pinot blanc",style:"dry, low aromatic intensity, medium acidity",band:1,why:{en:"Low aromatic intensity, because the dish itself has none: no browning, no spice. A wine with strong aroma would sit outside the plate.",fr:"Faible intensité aromatique, parce que le plat n'en a pas : ni coloration, ni épices. Un vin très aromatique resterait hors du plat."}},{appellation:"Côtes du Jura, chardonnay",style:"dry, part-oxidative, nutty notes",band:3,why:{en:"The oxidative notes meet the mushroom and the cooked butter of the roux; the acidity still handles the cream.",fr:"Les notes oxydatives rejoignent le champignon et le beurre cuit du roux ; l'acidité prend en charge la crème."}}]},

{id:"boudin-noir-aux-pommes",group:"charcuterie",name:{en:"Black pudding with apples",fr:"Boudin noir aux pommes"},
region:{en:"Normandie and northern France, with versions across the country",fr:"Normandie et Nord de la France, avec des versions dans tout le pays"},era:{en:"One of the oldest charcuteries, recorded in Apicius; the apple pairing is a northern French and Norman habit",fr:"L’une des plus anciennes charcuteries, mentionnée chez Apicius ; l’accord avec la pomme est une habitude normande et du Nord"},
summary:{en:"Pork blood sausage browned in butter and served with apples cooked until they hold their shape but no longer resist. It is the standard example of iron-rich richness answered by fruit acidity.",
fr:"Boudin de sang de porc coloré au beurre et servi avec des pommes cuites jusqu'à ce qu'elles tiennent encore sans résister. C'est l'exemple type d'une richesse ferreuse répondue par l'acidité d'un fruit."},
balance:{en:"Blood is iron and it is metallic and faintly sweet at once; the apple answers both at the same time, its malic acid cutting the fat while its own sugar sits alongside the sweetness already in the sausage. Choose a firm, acid apple — a reinette holds its shape and stays sour, where a soft dessert apple collapses into sweet purée and doubles the problem instead of solving it. The sausage is cooked at moderate heat and never pricked: the casing holds an emulsion of fat and blood that splits if it boils or bursts, and a split boudin turns grainy in seconds. Finish the pan with cider vinegar or calvados rather than cream — the dish needs another acid edge at the end, not more fat.",
fr:"Le sang, c'est du fer, à la fois métallique et légèrement sucré ; la pomme répond aux deux en même temps, son acide malique coupant le gras pendant que son sucre accompagne le sucré déjà présent dans le boudin. On choisit une pomme ferme et acide — une reinette tient à la cuisson et reste acidulée, là où une pomme de table molle s'effondre en purée sucrée et double le problème au lieu de le résoudre. Le boudin cuit à feu modéré et ne se pique jamais : le boyau retient une émulsion de gras et de sang qui se rompt s'il bout ou éclate, et un boudin tranché devient granuleux en quelques secondes. On déglace au vinaigre de cidre ou au calvados plutôt qu'à la crème — le plat demande une dernière arête acide, pas davantage de gras."},
ingredients:["boudin-noir","reinette-grise-du-canada","butter","cevennes-sweet-onion","calvados","cider-vinegar","cassonade","ratte-potato","black-pepper"],
techniques:["poeler","sauter","glacer-a-brun","deglacer","monter-au-beurre"],
wines:[{appellation:"Cidre de Normandie brut",style:"dry sparkling apple cider, low alcohol, high acidity, light tannin",band:1,why:{en:"Same fruit as the garnish; its acidity and carbonation cut the fat of the sausage, and its tannin is low enough not to meet the iron of the blood.",fr:"Le même fruit que la garniture ; son acidité et son gaz coupent le gras du boudin, et son tanin reste trop faible pour rencontrer le fer du sang."}},{appellation:"Saumur-Champigny, cabernet franc",style:"dry red, moderate tannin, high acidity, red fruit",band:2,why:{en:"Acidity carries the fat; tannin stays moderate, because high tannin against blood reads metallic.",fr:"L'acidité porte le gras ; le tanin reste modéré, car un tanin élevé sur le sang tourne métallique."}},{appellation:"Cloudy unfiltered apple juice, Normandy",style:"non-alcoholic, sweet, acidic, unfiltered",band:1,why:{en:"Its acidity performs the same cut as the cooked apple; the sweetness echoes the sugar in the sausage rather than opposing it.",fr:"Son acidité opère la même coupe que la pomme cuite ; le sucre fait écho à celui du boudin plutôt qu'il ne s'y oppose."}}]},

{id:"bouillabaisse",group:"france",name:{en:"Bouillabaisse",fr:"Bouillabaisse"},
region:{en:"Marseille, Provence",fr:"Marseille, Provence"},era:{en:"Old port dish; the Marseille charter fixed the modern service in 1980",fr:"Vieux plat de port ; la charte marseillaise a fixé le service moderne en 1980"},
summary:{en:"A soup of rockfish from the Marseille coast, served in two stages: the strained broth poured over bread, then the fish. What defines it is the hard boil, which forces the olive oil to emulsify into the water instead of floating on it.",
fr:"Soupe de poissons de roche de la côte marseillaise, servie en deux temps : le bouillon passé sur des tranches de pain, puis les poissons. Ce qui la définit, c'est la cuisson à gros bouillons, qui force l'huile d'olive à s'émulsionner dans l'eau au lieu de surnager."},
balance:{en:"The hard boil is the whole construction: violent agitation disperses the olive oil into the water as droplets, and the broth takes on body without flour or cream. Saffron and fennel carry the aromatic weight, while gelatine from the heads and bones gives the liquid its texture. The rouille adds a second load of fat, bound with egg and sharpened with garlic and chilli, so the bread underneath absorbs richness instead of soaking in thin stock. Potato acts as a blotter — a starch that takes up the emulsion and slows the palate between spoonfuls.",
fr:"Le gros bouillon est toute la construction : l'agitation violente disperse l'huile d'olive en gouttelettes dans l'eau, et le bouillon prend du corps sans farine ni crème. Le safran et le fenouil portent le poids aromatique, tandis que la gélatine des têtes et des arêtes donne sa texture au liquide. La rouille ajoute une seconde charge de gras, liée à l'œuf et relevée d'ail et de piment : le pain en dessous absorbe cette richesse au lieu de tremper dans un bouillon maigre. La pomme de terre sert de tampon — un amidon qui éponge l'émulsion et ralentit le palais entre deux cuillerées."},
ingredients:["red-scorpionfish","brown-scorpionfish","gurnard","conger","saffron","fennel","tomato","potato","garlic","onion","olive-oil","bigarade","egg","espelette"],
techniques:["ecailler","habiller","bouillir","mijoter","passer-au-chinois","emulsion-froide","concasser"],
wines:[{appellation:"Cassis blanc (Provence)",style:"dry white, unoaked, moderate to high acidity",band:3,why:{en:"The acidity cuts the emulsified olive oil in the broth, and the absence of oak leaves the saffron audible.",fr:"L'acidité coupe l'huile d'olive émulsionnée du bouillon, et l'absence de bois laisse le safran perceptible."}},{appellation:"Bandol rosé (Provence, mourvèdre)",style:"dry rosé, low tannin, medium body",band:3,why:{en:"Low tannin, because tannin clashes with the iodine of rockfish; enough body to stand against the fat of the rouille.",fr:"Peu de tanin, car le tanin heurte l'iode des poissons de roche ; assez de matière pour tenir face au gras de la rouille."}},{appellation:"Côtes de Provence blanc",style:"dry, light-bodied, citrus acidity",band:2,why:{en:"Citrus acidity does the work of a squeeze of lemon: it dissolves fat on the palate.",fr:"L'acidité d'agrume fait le travail d'un trait de citron : elle dissout le gras en bouche."}}]},

{id:"brandade-de-nimes",group:"france",name:{en:"Brandade de Nîmes",fr:"Brandade de Nîmes"},
region:{en:"Nîmes, Gard",fr:"Nîmes, Gard"},era:{en:"Attested 1786; spread after Durand's 1830 cookbook",fr:"Attestée en 1786 ; diffusée après le livre de cuisine de Durand, 1830"},
summary:{en:"Desalted salt cod worked warm with olive oil and cream into a smooth, pale emulsion. In Nîmes it carries no potato: the fish itself does the binding.",
fr:"Morue dessalée travaillée à chaud avec de l'huile d'olive et de la crème jusqu'à une émulsion lisse et pâle. À Nîmes elle ne comporte pas de pomme de terre : c'est le poisson lui-même qui lie."},
balance:{en:"This is a warm emulsion, not a purée: the protein and gelatine of the cod are the emulsifier, olive oil the fat phase, warm cream the liquid phase. Fish and fats must both be hot and the oil poured in a thin stream, exactly as for a mayonnaise, or the whole thing splits. Desalting sets the entire seasoning of the dish: too short and it is inedible, too long and the cod loses the salt that balances a mass of oil. Lemon and a little nutmeg are the only sharp and aromatic notes against a construction that is otherwise fat, salt and protein.",
fr:"C'est une émulsion chaude et non une purée : la protéine et la gélatine de la morue font l'émulsifiant, l'huile d'olive la phase grasse, la crème tiède la phase liquide. Le poisson et les corps gras doivent être chauds et l'huile versée en filet, exactement comme pour une mayonnaise, sinon l'ensemble tranche. Le dessalage fixe tout l'assaisonnement du plat : trop court il est immangeable, trop long la morue perd le sel qui équilibre une masse d'huile. Le citron et une pointe de muscade sont les seules notes vives et aromatiques face à une construction qui n'est par ailleurs que gras, sel et protéine."},
ingredients:["morue-salee","olive-oil","cream","garlic","lemon","nutmeg","white-pepper","bay-leaf"],
techniques:["degorger","pocher","emulsion-chaude","gratiner"],
wines:[{appellation:"Picpoul de Pinet (Languedoc)",style:"dry white, high acidity, saline finish",band:1,why:{en:"High acidity against a salted, fatty emulsion, and the saline note meets the cured cod.",fr:"Acidité haute face à une émulsion salée et grasse, et la note saline rejoint la morue."}},{appellation:"Costières de Nîmes blanc (grenache blanc, roussanne)",style:"dry white, medium body, moderate acidity",band:2,why:{en:"The body matches the weight of the emulsion, and the acidity dissolves the olive oil.",fr:"La matière répond au poids de l'émulsion, et l'acidité dissout l'huile d'olive."}},{appellation:"Tavel rosé (vallée du Rhône)",style:"dry rosé, full-bodied, light tannin",band:2,why:{en:"Enough structure for the fat, and little enough tannin not to clash with salt cod.",fr:"Assez de structure pour le gras, et assez peu de tanin pour ne pas heurter la morue."}}]},

{id:"boeuf-bourguignon",group:"france",name:{en:"Beef bourguignon",fr:"Bœuf bourguignon"},
region:{en:"Bourgogne",fr:"Bourgogne"},era:{en:"19th-century farmhouse cooking; codified by Escoffier in Le Guide culinaire, 1903",fr:"Cuisine de ferme du XIXe siècle ; codifié par Escoffier dans Le Guide culinaire, 1903"},
summary:{en:"Collagen-rich beef browned hard, then braised for hours in red wine with lardons, mushrooms and glazed pearl onions. The defining step is the initial searing: the dish is built on Maillard colour, which is what separates it from a southern daube.",
fr:"Morceaux de bœuf collagéneux fortement colorés, puis braisés des heures au vin rouge avec lardons, champignons et petits oignons glacés. L'étape qui le définit est la saisie initiale : le plat se construit sur la coloration de Maillard, ce qui le sépare d'une daube du Sud."},
balance:{en:"Three lines of flavour have to hold each other: the roasted bitterness of the searing, the acidity and tannin of the wine, and the fat of the lardons and the connective tissue. Long slow cooking turns collagen into gelatin, which gives the sauce body without any added starch and softens the tannin by binding to it. The pearl onions are glazed brown on purpose — their sugar is the only sweet element and it answers the acidity of the wine. Serve it with something starchy and neutral, potato or fresh noodles: the sauce is concentrated and the plate needs a surface to spread it on.",
fr:"Trois lignes de goût doivent se tenir : l'amertume de rôti de la saisie, l'acidité et le tanin du vin, le gras des lardons et du tissu conjonctif. La cuisson longue et douce transforme le collagène en gélatine, qui donne du corps à la sauce sans amidon ajouté et adoucit le tanin en s'y liant. Les petits oignons sont glacés à brun volontairement : leur sucre est le seul élément doux et il répond à l'acidité du vin. On sert avec un féculent neutre, pomme de terre ou pâtes fraîches : la sauce est concentrée, l'assiette a besoin d'une surface pour l'étaler."},
ingredients:["boeuf-charolais","paleron","macreuse","lard","pearl-onion","mushroom","carrot","onion","garlic","bay-leaf","thyme","parsley","flour-t55","black-pepper"],
techniques:["mariner","parer","rissoler","singer","deglacer","braiser","mijoter","glacer-a-brun"],
wines:[{appellation:"Bourgogne, pinot noir",style:"light to medium tannin, red fruit, high acidity",band:2,why:{en:"The same grape as the braising liquid, so the aromatic register matches; the acidity works against the fat of the lardons and the gelatin.",fr:"Le même cépage que le mouillement, donc le registre aromatique concorde ; l'acidité travaille contre le gras des lardons et la gélatine."}},{appellation:"Mercurey, Côte chalonnaise",style:"medium tannin, firm structure, dry",band:3,why:{en:"Firmer tannin holds up against the concentration of a long-reduced sauce; the gelatin coats the palate and blunts the tannin.",fr:"Un tanin plus ferme tient face à la concentration d'une sauce longuement réduite ; la gélatine nappe le palais et émousse le tanin."}},{appellation:"Beaujolais-Villages, gamay",style:"light tannin, high acidity, red fruit",band:1,why:{en:"Low tannin, because the dish already supplies structure through gelatin; the acidity is the only thing asked of the wine.",fr:"Peu de tanin, parce que le plat apporte déjà la structure par la gélatine ; on ne demande au vin que son acidité."}}]},

{id:"canard-a-l-orange",group:"france",name:{en:"Duck with bitter orange",fr:"Canard à l'orange"},
region:{en:"Paris; the bitter-orange method arrived through Italy and Spain.",fr:"Paris ; la méthode à l’orange amère est arrivée par l’Italie et l’Espagne."},era:{en:"Bitter-orange sauces recorded from the fourteenth century; codified as sauce bigarade in the nineteenth.",fr:"Sauces à l’orange amère attestées dès le XIVe siècle ; codifiées en sauce bigarade au XIXe."},
summary:{en:"A duck is roasted and basted, and the pan is deglazed into a stock-based sauce built on a caramel-vinegar gastrique and the juice and zest of bitter oranges. The sauce, not the bird, is the technical work.",
fr:"Le canard est rôti et arrosé, puis la plaque est déglacée dans une sauce au fond, construite sur une gastrique caramel-vinaigre et le jus et les zestes de bigarades. Le travail technique est dans la sauce, pas dans la volaille."},
balance:{en:"Duck carries a heavy subcutaneous fat layer that renders during roasting, and the whole sauce exists to answer it. The gastrique is the tool: sugar cooked to caramel and stopped with vinegar gives you sweetness and acidity in a single, adjustable element, so you can move the sauce in either direction late in the cooking. Bitter orange adds the third axis — pith and zest bring a bitterness that scrapes fat in a different way from acid, which is why sweet dessert oranges alone make the dish cloying. Learn the gastrique here and it transfers to any fatty roast: pork, goose, mackerel.",
fr:"Le canard porte une couche de gras sous-cutané qui fond à la cuisson, et toute la sauce existe pour lui répondre. La gastrique est l'outil : un sucre cuit au caramel et arrêté au vinaigre donne sucre et acidité dans un seul élément réglable, ce qui permet de déplacer la sauce dans un sens ou dans l'autre en fin de cuisson. La bigarade ajoute le troisième axe — zeste et ziste apportent une amertume qui racle le gras autrement que l'acidité, raison pour laquelle des oranges douces seules rendent le plat écœurant. Maîtrisez la gastrique ici et elle se transpose à tout rôti gras : porc, oie, maquereau."},
ingredients:["canard-de-barbarie","bigarade","orange","sugar","red-wine-vinegar","triple-sec","butter","black-pepper","salt"],
techniques:["brider","rotir","arroser","reposer-la-viande","fond-brun","gastrique","deglacer","reduction"],
wines:[{appellation:"Vouvray demi-sec (Chenin Blanc)",style:"Off-dry, residual sugar, high acidity.",band:2,why:{en:"Residual sugar matches the gastrique's sweetness while the acidity works on the rendered duck fat.",fr:"Le sucre résiduel répond à celui de la gastrique tandis que l'acidité agit sur le gras fondu du canard."}},{appellation:"Chinon rouge (Cabernet Franc)",style:"Light to medium tannin, red fruit, a bitter edge on the finish.",band:2,why:{en:"Its bitter finish sits alongside the orange zest, and the tannin binds to the fat of the skin.",fr:"Son amertume finale rejoint le zeste d'orange, et le tanin se lie au gras de la peau."}},{appellation:"Rivesaltes ambré",style:"Sweet, fortified, oxidative, notes of dried fruit and peel.",band:2,why:{en:"Sweetness matched to the gastrique; the oxidative peel character runs alongside the bitter orange.",fr:"Une douceur calée sur la gastrique ; le caractère oxydatif d'écorce longe la bigarade."}}]},

{id:"canele-de-bordeaux",group:"patisserie",name:{en:"Canelé",fr:"Canelé de Bordeaux"},
region:{en:"Bordeaux, Gironde",fr:"Bordeaux, Gironde"},era:{en:"Convent origin attributed to the Annonciades, 16th–17th century; current form fixed in the early 20th century",fr:"Origine conventuelle attribuée aux Annonciades, XVIe-XVIIe siècle ; forme actuelle fixée au début du XXe siècle"},
summary:{en:"A liquid batter of egg yolk, sugar, flour, vanilla and rum, rested for a day, then baked hard in a waxed copper mould. It comes out with a black caramelised shell around a soft, almost custard interior.",
fr:"Un appareil liquide de jaunes d'œufs, sucre, farine, vanille et rhum, reposé un jour, puis cuit fort dans un moule de cuivre ciré. Il sort avec une carapace noire caramélisée autour d'un intérieur souple, presque flan."},
balance:{en:"The whole dish is one contrast held together by the mould: copper conducts heat fast enough to burn the outside before the inside sets. Beeswax lining the mould melts, seals the surface and fries it from outside, which is why the crust is glassy rather than merely dark — plain butter gives a paler, softer result. The crust is caramelised past golden and is genuinely bitter, and that bitterness is what carries a batter which is otherwise very sweet and very rich in yolk. Resting the batter for a day lets the flour hydrate and the gluten relax, so the inside stays slack instead of rising like a cake.",
fr:"Tout le gâteau est un contraste tenu par le moule : le cuivre conduit assez vite pour brûler l'extérieur avant que l'intérieur ne prenne. La cire d'abeille qui chemise le moule fond, ferme la surface et la frit par l'extérieur — d'où une croûte vitrifiée et non simplement foncée ; au beurre seul, le résultat est plus pâle et plus mou. La croûte est poussée au-delà du blond et elle est franchement amère, et c'est cette amertume qui porte un appareil par ailleurs très sucré et très riche en jaunes. Le repos d'une journée hydrate la farine et détend le gluten, ce qui garde l'intérieur coulant au lieu de le faire lever comme un gâteau."},
ingredients:["flour-t45","egg","sugar","butter","cream","tahitian-vanilla","dark-rum","beeswax","salt"],
techniques:["infusion-a-froid","vanner","passer-au-chinois","chemiser","caramel-a-sec"],
wines:[{appellation:"Loupiac, sémillon et sauvignon",style:"Liquoreux, sucre élevé, acidité soutenue, notes d'abricot confit",band:2,why:{en:"The sugar sits above that of the caramelised shell, and the acidity cuts a batter whose richness comes from yolk and cream.",fr:"Le sucre se situe au-dessus de celui de la croûte caramélisée, et l'acidité tranche un appareil dont la richesse vient du jaune et de la crème."}},{appellation:"Rhum vieux traditionnel des Antilles",style:"Sec, 40 % vol., notes de vanille et de bois issues du fût",band:2,why:{en:"It repeats the rum and the vanilla already in the batter, and the dry spirit dissolves the fat rather than adding sugar to it.",fr:"Il reprend le rhum et la vanille déjà présents dans l'appareil, et l'alcool sec dissout le gras au lieu d'y ajouter du sucre."}},{appellation:"Café, arabica torréfaction moyenne",style:"Sans sucre, amertume nette, acidité modérée",band:1,why:{en:"Its bitterness runs parallel to the burnt crust and, carrying no sugar, it leaves the batter to supply the sweetness alone.",fr:"Son amertume est parallèle à celle de la croûte brûlée et, ne portant aucun sucre, elle laisse l'appareil fournir seul le sucré."}}]},

{id:"cassoulet",group:"france",name:{en:"Cassoulet",fr:"Cassoulet"},
region:{en:"Lauragais — Castelnaudary, Carcassonne, Toulouse",fr:"Lauragais — Castelnaudary, Carcassonne, Toulouse"},era:{en:"Descends from the medieval hericot de mouton; the modern form settles in the 19th century, and Prosper Montagné set out the three-city version in 1929",fr:"Descend de l’hericot de mouton médiéval ; la forme moderne se fixe au XIXe siècle, et Prosper Montagné énonce la version des trois villes en 1929"},
summary:{en:"White beans cooked with pork rind, then baked slowly with confit duck, Toulouse sausage and salted pork until a crust forms on top. The crust is broken back into the surface several times over the baking, and that repetition is the technique.",
fr:"Des haricots blancs cuits avec de la couenne, puis cuits lentement au four avec confit de canard, saucisse de Toulouse et porc salé, jusqu'à ce qu'une croûte se forme. On la casse et on la renfonce plusieurs fois au cours de la cuisson : cette répétition est la technique."},
balance:{en:"There is almost no acid in a cassoulet, which makes it the clearest lesson in the repertoire on fat carried by starch. Beans absorb rendered duck and pork fat into their own starch, so the fat is never loose on the plate — it is held, and the dish tastes rich rather than greasy. Pork rind supplies gelatin, which does the same work as a bound sauce and gives the whole thing a lip-coating texture without any flour. The only contrast is textural: breaking and reforming the crust builds a dry, browned surface over a soft interior, and without it the dish is a single uniform mouthful. The bean is not a filler here, it is the structural element.",
fr:"Il n'y a presque pas d'acide dans un cassoulet, ce qui en fait la leçon la plus claire du répertoire sur le gras porté par l'amidon. Les haricots absorbent la graisse fondue de canard et de porc dans leur propre amidon : le gras n'est jamais libre dans l'assiette, il est retenu, et le plat se lit riche et non gras. La couenne apporte la gélatine, qui fait le travail d'une sauce liée et donne une texture qui colle aux lèvres sans aucune farine. Le seul contraste est de texture : casser et refaire la croûte construit une surface sèche et colorée sur un intérieur fondant, et sans elle le plat n'est qu'une bouchée uniforme. Le haricot n'est pas un remplissage, c'est l'élément porteur."},
ingredients:["haricot-tarbais","confit-de-canard","saucisse-de-toulouse","poitrine-de-porc","couenne","jarret-de-porc","garlic","onion","carrot","clove","bay-leaf","thyme","black-pepper","duck-fat"],
techniques:["blanchir","confire","rissoler","mijoter","a-l-etouffee","gratiner","depouiller"],
wines:[{appellation:"Cahors, malbec",style:"high tannin, dark fruit, dry",band:2,why:{en:"High tannin against a dish with no acidity of its own: the tannin binds to the fat and gelatin and clears the palate between mouthfuls.",fr:"Un tanin élevé face à un plat sans acidité propre : le tanin se lie au gras et à la gélatine et nettoie le palais entre deux bouchées."}},{appellation:"Madiran, tannat",style:"high tannin, firm, dry",band:2,why:{en:"Tannat carries the most tannin of the region's grapes, which is what a dish this rich and this unacidic asks for.",fr:"Le tannat est le cépage le plus tannique de la région, ce que demande un plat aussi riche et aussi peu acide."}},{appellation:"Corbières, carignan and grenache",style:"medium tannin, dry, herbal notes",band:1,why:{en:"Medium tannin and a herbal register that runs alongside the thyme and bay in the pot.",fr:"Tanin moyen et registre herbacé qui suit le thym et le laurier de la cassole."}}]},

{id:"ceviche-de-bar",group:"monde",name:{en:"Sea bass ceviche",fr:"Ceviche de bar"},
region:{en:"Peruvian coast",fr:"Côte péruvienne"},era:{en:"Pre-Hispanic base, current form in the 20th century",fr:"Base préhispanique, forme actuelle au XXe siècle"},
summary:{en:"Cubed raw fish salted, then dressed with lime juice, sliced red onion, ají amarillo and coriander, and served with sweet potato and boiled corn. The raw-fish-and-acid practice is pre-Hispanic; lime arrived with the Spanish in the sixteenth century.",
fr:"Du poisson cru taillé en cubes, salé, puis assaisonné au jus de citron vert, à l'oignon rouge émincé, à l'ají amarillo et à la coriandre, servi avec patate douce et maïs bouilli. La pratique du poisson cru à l'acide est préhispanique ; le citron vert est arrivé avec les Espagnols au XVIe siècle."},
balance:{en:"The acid of the lime denatures the proteins of the fish: the flesh turns opaque and firm without ever meeting heat. Time is the only control — a few minutes is enough, the acid does not stop working, and a long marinade leaves the flesh chalky and dry. Salt goes on before the lime, seasoning the fish and drawing out a little water; the red onion is rinsed to strip its sulphurous bite. There is no fat anywhere in the dish, so the sweet potato and the corn carry the sugar and starch that answer the acid and the heat of the ají, and they are the only thing softening the plate.",
fr:"L'acide du citron vert dénature les protéines du poisson : la chair devient opaque et ferme sans jamais passer par la chaleur. Le temps est la seule commande — quelques minutes suffisent, l'acide ne s'arrête pas, et une marinade longue laisse la chair crayeuse et sèche. Le sel vient avant le citron, il assaisonne le poisson et fait sortir un peu d'eau ; l'oignon rouge est rincé pour lui ôter son mordant soufré. Il n'y a aucun gras dans le plat, la patate douce et le maïs portent donc le sucre et l'amidon qui répondent à l'acide et au piquant de l'ají, et ils sont la seule chose qui adoucit l'assiette."},
ingredients:["sea-bass","lime","red-onion","aji-amarillo","cilantro","salt","sweet-potato","corn","celery","garlic","ginger"],
techniques:["ceviche","mariner","emincer","tailler-en-brunoise","passer-au-chinois"],
wines:[{appellation:"Rías Baixas, albariño",style:"blanc sec, acidité élevée, salin, sans bois",band:2,why:{en:"Its acidity has to match the lime, or the wine reads flat next to the marinade; the salinity follows the raw fish.",fr:"Son acidité doit égaler celle du citron vert, sinon le vin paraît plat à côté de la marinade ; la salinité suit le poisson cru."}},{appellation:"Muscadet Sèvre-et-Maine sur lie",style:"blanc sec, acidité élevée, sans élevage sous bois",band:1,why:{en:"No oak, because oak tannin against raw fish gives a metallic result; the acidity holds level with the lime.",fr:"Pas de bois, parce que le tanin du fût sur du poisson cru donne un résultat métallique ; l'acidité se tient au niveau du citron vert."}},{appellation:"Cava brut nature",style:"effervescent, sans dosage, acidité élevée",band:2,why:{en:"Zero dosage, since added sugar sits awkwardly on a dish built entirely on acid; the bubbles carry the chilli heat away.",fr:"Aucun dosage, le sucre ajouté se tient mal sur un plat entièrement construit sur l'acide ; les bulles emportent le piquant."}}]},

{id:"choucroute-garnie",group:"france",name:{en:"Garnished sauerkraut",fr:"Choucroute garnie"},
region:{en:"Alsace; the garnished form as we know it took shape in Paris brasseries",fr:"Alsace ; la forme garnie telle qu’on la connaît prend corps dans les brasseries parisiennes"},era:{en:"Fermented cabbage documented in Alsace from the 13th century, as Gumbskrüt; choucroute garnie spread from 1870, when Alsatians opened brasseries in Paris",fr:"Chou fermenté attesté en Alsace dès le XIIIe siècle, sous le nom de Gumbskrüt ; la choucroute garnie se répand à partir de 1870, quand les Alsaciens ouvrent des brasseries à Paris"},
summary:{en:"Lacto-fermented cabbage braised slowly with smoked and salted pork, sausages and potatoes. The cabbage is not cooked to soften it — it is already edible — but to let the meat fat move into it while its acidity moves the other way.",
fr:"Chou lacto-fermenté braisé lentement avec porc fumé et salé, saucisses et pommes de terre. On ne cuit pas le chou pour l'attendrir — il est déjà comestible — mais pour que le gras des viandes passe en lui pendant que son acidité passe en sens inverse."},
balance:{en:"Lactic acid is the whole mechanism: fermentation has already loaded the cabbage with an acid that cuts smoked pork fat mouthful for mouthful, so the dish needs no sauce, no wine reduction and no vinegar. How sharp it ends up is a decision, not an accident — rinsing the sauerkraut once or twice removes acid, not rinsing it keeps it, and that is the single adjustment a cook makes. Juniper and clove are aromatic counterweights to smoke, which otherwise dominates everything. The potato is the neutral element: it takes the fat that the cabbage cannot hold and gives the plate a mouthful with no acid in it, which is what makes the acid readable when you go back to the cabbage.",
fr:"L'acide lactique est tout le mécanisme : la fermentation a déjà chargé le chou d'un acide qui tranche le gras du porc fumé bouchée après bouchée, si bien que le plat n'a besoin ni de sauce, ni de réduction de vin, ni de vinaigre. Le niveau d'acidité final est une décision, pas un hasard — rincer la choucroute une ou deux fois enlève de l'acide, ne pas la rincer le garde : c'est le seul réglage du cuisinier. Le genièvre et le clou de girofle sont les contrepoids aromatiques du fumé, qui sinon écrase tout. La pomme de terre est l'élément neutre : elle prend le gras que le chou ne peut retenir et donne une bouchée sans acide, ce qui rend l'acide de nouveau lisible quand on revient au chou."},
ingredients:["sauerkraut","poitrine-fumee","jarret-de-porc","saucisse-de-montbeliard","saucisse-de-morteau","petit-sale","couenne","juniper","bay-leaf","clove","onion","black-pepper","bintje-potato","lard"],
techniques:["lacto-fermentation","blanchir","etuver","a-l-etouffee","braiser","salaison","pocher"],
wines:[{appellation:"Alsace riesling",style:"dry, very high acidity, citrus and mineral notes",band:2,why:{en:"Acidity aligned with the lactic acid of the cabbage, so the wine extends the mechanism the dish already uses on the pork fat.",fr:"Une acidité alignée sur l'acide lactique du chou : le vin prolonge le mécanisme que le plat applique déjà au gras du porc."}},{appellation:"Alsace sylvaner",style:"dry, medium acidity, low aroma",band:1,why:{en:"Low aromatic intensity, because smoke and juniper already occupy the aromatic space; the wine is there for acidity alone.",fr:"Faible intensité aromatique, le fumé et le genièvre occupant déjà l'espace ; le vin n'est là que pour l'acidité."}},{appellation:"Crémant d'Alsace",style:"dry sparkling, high acidity, fine bubble",band:2,why:{en:"Carbon dioxide and acidity together scour fat from the palate; a mechanical effect on top of the chemical one.",fr:"Le gaz carbonique et l'acidité décapent ensemble le gras du palais : un effet mécanique en plus de l'effet chimique."}},{appellation:"Cidre de Bretagne, brut",style:"dry sparkling, malic acidity, no alcohol above light levels",band:1,why:{en:"Malic acidity and bubble against pork fat, on the same principle as the crémant; the lower alcohol keeps the palate from tiring on a long dish.",fr:"Acidité malique et bulle contre le gras du porc, sur le même principe que le crémant ; le degré plus bas évite la fatigue du palais sur un plat long."}}]},

{id:"clafoutis",group:"patisserie",name:{en:"Clafoutis",fr:"Clafoutis limousin"},
region:{en:"Limousin",fr:"Limousin"},era:{en:"Around 1860, spread across France by the late 19th century",fr:"Vers 1860, diffusé dans toute la France à la fin du XIXe siècle"},
summary:{en:"Black cherries set in a thin egg and flour batter, baked until it takes. Traditionally the stones are left in, and the recipe is a farm dessert made when cherries were abundant.",
fr:"Des cerises noires prises dans un appareil fin aux œufs et à la farine, cuit jusqu'à prise. Traditionnellement les noyaux restent, et la recette est un dessert de ferme fait quand les cerises abondaient."},
balance:{en:"A clafoutis is a set custard with just enough flour to hold it — the flour makes it sliceable, the eggs make it tender, and too much of either gives cake or scrambled egg. Cherries release water as they heat, so the batter has to be able to absorb it without weeping; this is why the batter is thin but not watery and why the dish is baked hot. Unpitted cherries release traces of benzaldehyde from the stones, the same compound that gives bitter almond its smell, and that faint bitterness is the counterweight to the fruit sugar. Salt and the acidity of the cherry do the rest of the work against a base that is otherwise egg, cream and sugar.",
fr:"Un clafoutis est un appareil à crème prise avec juste assez de farine pour le tenir : la farine le rend tranchable, les œufs le gardent moelleux, et un excès de l'un ou de l'autre donne du gâteau ou de l'œuf brouillé. Les cerises rendent de l'eau en chauffant, donc l'appareil doit pouvoir l'absorber sans rendre de jus ; d'où un appareil fin mais pas liquide, et une cuisson chaude. Les cerises non dénoyautées libèrent des traces de benzaldéhyde depuis le noyau, la molécule de l'amande amère, et cette légère amertume fait contrepoids au sucre du fruit. Le sel et l'acidité de la cerise font le reste du travail face à une base qui n'est sinon qu'œuf, crème et sucre."},
ingredients:["griotte","cherry","egg","sugar","flour-t55","cream","butter","vanilla","salt","kirsch"],
techniques:["appareil-a-creme-prise","maceration","vanner","passer-au-chinois"],
wines:[{appellation:"Bugey-Cerdon, gamay et poulsard",style:"Rosé effervescent, sucre résiduel léger, fruit rouge, faible alcool",band:1,why:{en:"The carbonation lifts a dense set custard, and the red fruit sits in the same aromatic family as the cherry rather than adding a new one.",fr:"La bulle allège un flan dense, et le fruit rouge appartient à la même famille aromatique que la cerise plutôt que d'en ajouter une autre."}},{appellation:"Rasteau, vin doux naturel de grenache noir",style:"Muté, sucre résiduel élevé, tanin faible, fruit noir",band:2,why:{en:"The residual sugar supports the cherry; the tannin stays low because tannin against an egg custard produces a metallic sensation.",fr:"Le sucre résiduel soutient la cerise ; le tanin reste bas car un tanin marqué sur un flan aux œufs donne une sensation métallique."}},{appellation:"Kirsch de Fougerolles AOC",style:"Eau-de-vie de cerise, sec, 45 % vol., notes de noyau",band:2,why:{en:"Same raw material as the fruit in the dish, including the stone note, and the dry spirit dissolves the fat of the custard on the palate.",fr:"Même matière première que le fruit du plat, note de noyau comprise, et l'alcool sec dissout le gras du flan en bouche."}}]},

{id:"coq-au-vin",group:"france",name:{en:"Coq au vin",fr:"Coq au vin"},
region:{en:"Bourgogne; also claimed by Auvergne, in the Chanturgue version",fr:"Bourgogne ; revendiqué aussi par l’Auvergne, dans la version au chanturgue"},era:{en:"Fixed in the 19th and 20th centuries; the Vercingétorix story is a late legend, not a source",fr:"Fixé aux XIXe et XXe siècles ; l’histoire de Vercingétorix est une légende tardive, pas une source"},
summary:{en:"An old cock jointed and braised in red wine with lardons, mushrooms and pearl onions, after a marinade of a day or more. The classical finish is a liaison with blood and liver, which thickens the sauce without flour and turns it dark.",
fr:"Un vieux coq découpé et braisé au vin rouge avec lardons, champignons et petits oignons, après une marinade d'un jour ou plus. La finition classique est une liaison au sang et au foie, qui lie la sauce sans farine et la fonce."},
balance:{en:"The bird is the reason for every step: an old cock has tough, heavily worked muscle and a lot of connective tissue, so it needs acid to break down and hours of gentle heat to become tender. The marinade does the first job, the braise the second, and a young chicken put through the same treatment falls apart into dry fibres. The blood-and-liver liaison thickens through protein rather than starch, which is why the sauce stays glossy and tastes only of itself. Glazed onions and the fat of the lardons are the counterweight to the wine's acidity; without them the sauce reads harsh.",
fr:"La volaille commande chaque étape : un vieux coq a un muscle dur, très sollicité, et beaucoup de tissu conjonctif — il lui faut de l'acide pour se défaire et des heures de chaleur douce pour s'attendrir. La marinade fait le premier travail, le braisage le second ; un poulet jeune soumis au même traitement se défait en fibres sèches. La liaison au sang et au foie lie par les protéines et non par l'amidon : la sauce reste brillante et ne goûte qu'elle-même. Les oignons glacés et le gras des lardons sont le contrepoids de l'acidité du vin ; sans eux la sauce est dure."},
ingredients:["coq","foie-de-volaille","lard","pearl-onion","mushroom","carrot","onion","garlic","bay-leaf","thyme","parsley","marc-de-bourgogne","black-pepper"],
techniques:["habiller","mariner","rissoler","flamber","braiser","depouiller","reduction","glacer-a-brun"],
wines:[{appellation:"Bourgogne, pinot noir",style:"light to medium tannin, high acidity, red fruit",band:2,why:{en:"The braising wine and the poured wine share a grape, so the acidity in the glass reads as continuous with the sauce.",fr:"Le vin de cuisson et le vin servi partagent le cépage : l'acidité du verre se lit dans la continuité de la sauce."}},{appellation:"Côtes d'Auvergne, gamay",style:"light tannin, high acidity, dry",band:2,why:{en:"Low tannin, because the liver-and-blood liaison already coats the palate; added tannin on top of it turns dry.",fr:"Peu de tanin, parce que la liaison au foie et au sang nappe déjà le palais ; un tanin ajouté par-dessus assèche."}},{appellation:"Chinon, cabernet franc",style:"medium tannin, high acidity, vegetal and peppery notes",band:2,why:{en:"The acidity carries the fat of the lardons; the peppery register runs alongside the black pepper in the braise.",fr:"L'acidité prend le gras des lardons ; le registre poivré suit le poivre du braisage."}}]},

{id:"creme-brulee",group:"patisserie",name:{en:"Crème brûlée",fr:"Crème brûlée"},
region:{en:"France, court service then general repertoire",fr:"France, service de cour puis répertoire général"},era:{en:"First printed recipe in 1691 in Massialot, flavoured with cinnamon and lemon zest",fr:"Première recette imprimée en 1691 chez Massialot, parfumée cannelle et zeste de citron"},
summary:{en:"A baked cream set with egg yolks alone, chilled, then covered with sugar burnt to a hard sheet at the last moment. Two temperatures and two textures in the same spoon.",
fr:"Une crème cuite prise aux seuls jaunes d'œufs, refroidie, puis couverte d'un sucre brûlé en plaque dure au dernier moment. Deux températures et deux textures dans la même cuillère."},
balance:{en:"Yolks set between roughly 65 and 80 degrees, so the cream is baked gently and pulled while it still trembles; carried past that point the proteins tighten and squeeze out water, which is the grainy, weeping result. The set custard is fat, cold and barely sweet — it is the burnt sugar on top that supplies both the sweetness and, more importantly, the bitterness of caramel. Contrast is the whole point: hot brittle crust against cold soft cream, and the crust must be made within minutes of service or it dissolves into the surface. The original perfume was cinnamon and lemon zest rather than vanilla, and either aromatic works because both are there to give the fat something to carry.",
fr:"Les jaunes prennent entre 65 et 80 degrés environ : la crème cuit donc doucement et sort quand elle tremble encore ; poussée au-delà, les protéines se resserrent et expulsent l'eau, d'où le résultat granuleux qui rend du jus. La crème prise est grasse, froide et à peine sucrée — c'est le sucre brûlé du dessus qui apporte le sucré et, surtout, l'amertume du caramel. Le contraste est le sujet même : croûte chaude et cassante contre crème froide et souple, et cette croûte doit être faite quelques minutes avant le service, sinon elle se dissout en surface. Le parfum d'origine était cannelle et zeste de citron plutôt que vanille, et les deux fonctionnent parce qu'ils sont là pour donner au gras quelque chose à transporter."},
ingredients:["cream","egg","sugar","tahitian-vanilla","cassonade","salt","lemon","cinnamon"],
techniques:["appareil-a-creme-prise","infusion-a-froid","passer-au-chinois","vanner","caramel-a-sec"],
wines:[{appellation:"Sauternes, sémillon botrytisé",style:"Liquoreux, sucre élevé, acidité soutenue, notes de miel et d'abricot confit",band:3,why:{en:"The sugar exceeds that of the burnt crust so the wine is not read as dry, while the acidity cuts a custard that is almost pure cream and yolk.",fr:"Le sucre dépasse celui de la croûte brûlée, donc le vin n'est pas perçu comme sec, et l'acidité tranche une crème qui n'est presque que crème et jaune."}},{appellation:"Madère Malmsey",style:"Muté, chauffé et oxydé, sucre élevé, acidité volatile marquée",band:3,why:{en:"The estufagem produces cooked-sugar and caramel compounds close to those of the burnt crust, and the high acidity offsets the fat of the cream.",fr:"L'estufagem produit des composés de sucre cuit et de caramel proches de ceux de la croûte brûlée, et l'acidité élevée compense le gras de la crème."}},{appellation:"Jurançon moelleux, petit manseng",style:"Moelleux, acidité très élevée, notes d'agrume et de fruit exotique",band:2,why:{en:"Petit manseng keeps unusually high acidity at high sugar, which is what a dessert of this fat content requires to avoid coating the palate.",fr:"Le petit manseng conserve une acidité très élevée à sucre élevé, ce qu'exige un dessert aussi gras pour ne pas tapisser le palais."}}]},

{id:"daube-provencale",group:"france",name:{en:"Provençal daube",fr:"Daube provençale"},
region:{en:"Provence",fr:"Provence"},era:{en:"18th century; the name comes from the Provençal adobar, to prepare or to marinate",fr:"XVIIIe siècle ; le nom vient du provençal adobar, préparer ou mariner"},
summary:{en:"Beef marinated overnight in red wine with orange peel and herbs, then cooked very slowly in a closed pot. It is defined against bourguignon by that marinade and by the light or absent searing: the flavour is built by steeping, not by browning.",
fr:"Bœuf mariné une nuit au vin rouge avec zeste d'orange et herbes, puis cuit très lentement en vase clos. Elle se définit contre le bourguignon par cette marinade et par une saisie légère ou absente : le goût se construit par macération, non par coloration."},
balance:{en:"Without a hard searing there is no Maillard bitterness, so the bitter note is supplied deliberately — orange peel, and often a piece of cinnamon or a little clove. That bitterness is what stands up to the beef fat, in the place where a bourguignon would use roasted crust. The marinade's acid starts breaking down connective tissue before any heat is applied, which is why the meat can then be cooked at a very low temperature in a sealed pot without drying: the traditional daubière has a concave lid filled with water so steam condenses and falls back in. Black olives are added late and bring salt, not flavour depth; a daube is at its best reheated, because a day in the cold lets the gelatin set and the fat rise to be lifted off.",
fr:"Sans saisie franche, pas d'amertume de Maillard : la note amère est donc apportée volontairement — zeste d'orange, souvent un bâton de cannelle ou un peu de girofle. C'est cette amertume qui tient tête au gras du bœuf, là où un bourguignon utiliserait sa croûte de rôti. L'acide de la marinade commence à défaire le tissu conjonctif avant toute chaleur, ce qui permet ensuite une cuisson très basse en vase clos sans dessèchement : la daubière traditionnelle a un couvercle creux qu'on remplit d'eau, pour que la vapeur se condense et retombe. Les olives noires entrent tard et apportent du sel, non de la profondeur ; une daube est meilleure réchauffée, parce qu'une nuit au froid fige la gélatine et fait remonter le gras, qu'on retire."},
ingredients:["paleron","beef-cheek","lard","carrot","onion","garlic","tomato","olive-nyons","orange","bay-leaf","thyme","savory","black-pepper","cinnamon"],
techniques:["mariner","larder","parer","rissoler","deglacer","a-l-etouffee","mijoter","reduction"],
wines:[{appellation:"Bandol, mourvèdre",style:"high tannin, dry, dark fruit and leather notes",band:3,why:{en:"Firm tannin against the gelatin of cheek and chuck; the gelatin coats the palate and softens the tannin in return.",fr:"Un tanin ferme contre la gélatine de la joue et du paleron ; la gélatine nappe le palais et adoucit le tanin en retour."}},{appellation:"Gigondas, grenache and syrah",style:"medium to high tannin, dry, garrigue and pepper notes",band:2,why:{en:"The herbal register matches the thyme, savory and bay in the marinade; the tannin meets the fat.",fr:"Le registre herbacé rejoint le thym, la sarriette et le laurier de la marinade ; le tanin rencontre le gras."}},{appellation:"Côtes de Provence, rouge",style:"medium tannin, dry, red fruit",band:2,why:{en:"Moderate tannin, since the dish is barely browned and offers no roasted bitterness for a heavier structure to work against.",fr:"Un tanin modéré, le plat étant peu coloré et n'offrant aucune amertume de rôti à opposer à une structure plus lourde."}}]},

{id:"ficelle-picarde",group:"france",name:{en:"Ficelle picarde",fr:"Ficelle picarde"},
region:{en:"Amiens, Picardie",fr:"Amiens, Picardie"},era:{en:"Created in the 1950s for a fair in Amiens",fr:"Créée dans les années 1950 pour une foire à Amiens"},
summary:{en:"A crêpe rolled around ham and a mushroom duxelles, coated with cream and cheese and browned in the oven. Born in Amiens in the mid-twentieth century, it is a gratin built on a pancake.",
fr:"Crêpe roulée autour de jambon et d'une duxelles de champignons, nappée de crème et de fromage puis gratinée. Née à Amiens au milieu du XXe siècle, c'est un gratin monté sur une crêpe."},
balance:{en:"Three layers of dairy fat — crêpe batter, béchamel, cream and cheese — are held apart by the mushrooms and the ham. The duxelles is dried out first: mushrooms release a great deal of water, and without evaporation the béchamel loosens and the crêpe goes soggy. The ham brings salt and the acidity of curing, the only thing pushing back against the fat. Browning gives a Maillard crust and a bitterness that stop a very rich dish from reading as a single soft, creamy note.",
fr:"Trois couches de gras laitier — pâte à crêpe, béchamel, crème et fromage — sont séparées par les champignons et le jambon. La duxelles est d'abord asséchée : les champignons rendent beaucoup d'eau, et sans évaporation la béchamel se délie et la crêpe se détrempe. Le jambon apporte le sel et l'acidité de la salaison, seule chose qui s'oppose au gras. Le gratinage donne une croûte de Maillard et une amertume qui empêchent un plat très riche de se lire comme une seule note douce et crémeuse."},
ingredients:["flour-t45","egg","butter","mushroom","shallot","jambon-de-paris","creme-fraiche","gruyere","nutmeg","black-pepper"],
techniques:["vanner","ciseler","sauter","roux-blanc","masquer","gratiner"],
wines:[{appellation:"Chablis (Bourgogne, chardonnay)",style:"dry white, high acidity, unoaked",band:3,why:{en:"The acidity cuts three layers of dairy fat, and the absence of oak adds no weight to an already rich plate.",fr:"L'acidité coupe trois couches de gras laitier, et l'absence de bois n'ajoute pas de poids à un plat déjà riche."}},{appellation:"Bourgogne aligoté",style:"dry white, light body, high acidity",band:2,why:{en:"Sharp acidity against the béchamel, in a light body that does not compete with the sauce.",fr:"Une acidité vive face à la béchamel, dans un corps léger qui ne concurrence pas la sauce."}},{appellation:"Cidre brut de Normandie",style:"dry sparkling cider, low degree, apple acidity, carbonation",band:1,why:{en:"Carbonation lifts the fat off the palate, and the apple acidity does what a squeeze of lemon would.",fr:"Le gaz décolle le gras du palais, et l'acidité de pomme fait ce que ferait un trait de citron."}}]},

{id:"garbure",group:"france",name:{en:"Garbure",fr:"Garbure"},
region:{en:"Béarn, Gascogne, Pyrénées",fr:"Béarn, Gascogne, Pyrénées"},era:{en:"The Gascon term garburo is attested in the medieval period; the French form garbure is recorded by around 1750",fr:"Le terme gascon garburo est attesté au Moyen Âge ; la forme française garbure est relevée vers 1750"},
summary:{en:"A thick cabbage and bean soup built on a cured ham bone, with root vegetables and a piece of confit added late. It was the daily one-pot meal of the Pyrenean farm, and its thickness is the measure of it: a spoon should stand in it.",
fr:"Soupe épaisse de chou et de haricots montée sur un os de jambon, avec légumes racines et un morceau de confit ajouté tard. C'était le plat unique quotidien de la ferme pyrénéenne, et son épaisseur en est la mesure : la cuillère doit y tenir debout."},
balance:{en:"The ham bone is the seasoning system: it releases salt and gelatin slowly over hours, which is why garbure is salted at the end or not at all. Bean starch and collapsed potato thicken the liquid with no flour and no cream, and once thickened it holds the fat of the confit in suspension instead of letting it float. Cabbage brings a faint bitterness and a sulphurous note that keep the fat from reading flat; it goes in late, since long cooking turns that note acrid. The dish is deliberately monotone in texture, so the contrast has to be built at the table — bread, or a piece of confit skin crisped separately.",
fr:"L'os de jambon est le système d'assaisonnement : il libère sel et gélatine lentement, sur des heures, raison pour laquelle on sale la garbure à la fin, ou pas du tout. L'amidon des haricots et la pomme de terre défaite épaississent le liquide sans farine ni crème, et une fois épaissi il tient le gras du confit en suspension au lieu de le laisser surnager. Le chou apporte une légère amertume et une note soufrée qui empêchent le gras d'être plat ; il entre tard, une cuisson longue rendant cette note âcre. Le plat est volontairement monotone de texture : le contraste se construit à table — du pain, ou une peau de confit croustillée à part."},
ingredients:["haricot-tarbais","cabbage","confit-de-canard","jambon-de-bayonne","potato","carrot","turnip","leek","garlic","thyme","bay-leaf","graisse-doie","black-pepper","couenne"],
techniques:["salaison","blanchir","mijoter","a-l-etouffee","depouiller","confire","tailler-en-paysanne"],
wines:[{appellation:"Madiran, tannat",style:"high tannin, dry, dark fruit",band:2,why:{en:"Tannin against goose and duck fat held in the broth; the salt from the ham bone lowers the tannic impression.",fr:"Le tanin contre le gras d'oie et de canard tenu dans le bouillon ; le sel de l'os de jambon abaisse l'impression tannique."}},{appellation:"Jurançon sec, gros manseng",style:"dry, high acidity, citrus notes",band:2,why:{en:"An acid rather than tannic answer to the same fat, which leaves the vegetables more legible.",fr:"Une réponse acide plutôt que tannique au même gras, qui laisse les légumes plus lisibles."}},{appellation:"Irouléguy, tannat and cabernet franc",style:"medium to high tannin, dry, firm",band:3,why:{en:"Local tannin structure against confit fat, with the acidity of cabernet franc alongside it.",fr:"Structure tannique locale contre le gras de confit, avec l'acidité du cabernet franc en soutien."}}]},

{id:"gratin-dauphinois",group:"france",name:{en:"Gratin dauphinois",fr:"Gratin dauphinois"},
region:{en:"Dauphiné: Isère, Drôme, Hautes-Alpes.",fr:"Dauphiné : Isère, Drôme, Hautes-Alpes."},era:{en:"Named in writing in 1788; settled in its cream form during the nineteenth century.",fr:"Nommé par écrit en 1788 ; fixé dans sa forme à la crème au XIXe siècle."},
summary:{en:"Raw potatoes are sliced thin, cooked slowly in cream in a garlic-rubbed dish, and finished until the top browns. There is no cheese and no roux in the traditional version.",
fr:"Des pommes de terre crues sont émincées finement, cuites doucement à la crème dans un plat frotté d'ail, puis colorées en fin de cuisson. La version traditionnelle ne comporte ni fromage ni roux."},
balance:{en:"The thickener is inside the ingredient: starch leaches out of the raw slices and sets the cream, which is why the potatoes go in raw and never blanched. Choose a floury variety and the liquid binds; choose a waxy one and it stays soupy — the variety is a technical decision, not a preference. Fat and starch alone would be heavy and dull, so the seasoning does the balancing work: garlic, nutmeg and a firm hand with the pepper. The contrast is textural rather than acidic — a browned, slightly dry crust over a soft, bound interior.",
fr:"Le liant est dans l'ingrédient : l'amidon sort des tranches crues et prend la crème, raison pour laquelle les pommes de terre entrent crues et jamais blanchies. Une variété farineuse et le liquide lie ; une variété à chair ferme et le gratin reste liquide — le choix de la variété est une décision technique, pas un goût. Graisse et amidon seuls seraient lourds et sourds : c'est l'assaisonnement qui équilibre, ail, muscade et poivre sans timidité. Le contraste est de texture et non d'acidité — une croûte colorée et un peu sèche sur un intérieur moelleux et lié."},
ingredients:["bintje-potato","cream","creme-fraiche","butter","garlic","nutmeg","white-pepper","salt"],
techniques:["emincer","chemiser","etuver","mijoter","gratiner"],
wines:[{appellation:"Roussette de Savoie (Altesse)",style:"Dry, firm acidity, moderate body.",band:2,why:{en:"Acidity cuts a dish that is fat and starch with no acid of its own.",fr:"L'acidité tranche un plat qui n'est que graisse et amidon, sans acidité propre."}},{appellation:"Crozes-Hermitage blanc (Marsanne, Roussanne)",style:"Dry, broad, low acidity, mild bitterness on the finish.",band:2,why:{en:"The bitter finish gives contrast where acidity alone would be thin against cream.",fr:"L'amertume finale apporte le contraste là où l'acidité seule serait maigre face à la crème."}},{appellation:"Beaujolais-Villages (Gamay)",style:"Light tannin, red fruit, served cool.",band:1,why:{en:"Low tannin, because tannin and cream both coat the palate; the acidity does the cutting instead.",fr:"Peu de tanin, car tanin et crème tapissent tous deux le palais ; c'est l'acidité qui tranche."}}]},

{id:"homard-a-l-americaine",group:"france",name:{en:"Lobster à l'américaine",fr:"Homard à l'américaine"},
region:{en:"Paris; a Mediterranean method applied to Atlantic lobster.",fr:"Paris ; une méthode méditerranéenne appliquée au homard atlantique."},era:{en:"Around 1860, attributed to a Sétois chef in Paris; printed as 'armoricaine' in some later texts.",fr:"Vers 1860, attribué à un chef sétois installé à Paris ; imprimé « à l’armoricaine » dans certains textes postérieurs."},
summary:{en:"Live lobster is cut up in the shell, seared in oil, flamed with cognac and simmered with tomato, shallot and garlic. The sauce is finished with the coral and butter, which thicken it.",
fr:"Le homard est tronçonné vivant en carapace, saisi à l'huile, flambé au cognac puis mijoté avec tomate, échalote et ail. La sauce est finie au corail et au beurre, qui l'épaississent."},
balance:{en:"The flavour is in the shell, not the flesh, which is why the lobster is cut up raw and cooked in its carapace — the pieces are a cooking vessel before they are a portion. The coral is the liaison: it is protein-rich and sets when warmed, so it thickens the sauce without flour, and it must never boil after it goes in. Tomato and wine supply the acidity that a rich shellfish butter needs, and the olive oil marks the dish as southern in method however Atlantic the animal. Lobster flesh overcooks in a minute, so it comes out while the sauce reduces and returns only to warm through.",
fr:"Le goût est dans la carapace, pas dans la chair : c'est pourquoi le homard est tronçonné cru et cuit en coquille — les morceaux sont un ustensile avant d'être une portion. Le corail fait la liaison : riche en protéines, il prend à la chaleur et épaissit la sauce sans farine, à condition de ne jamais bouillir une fois incorporé. La tomate et le vin donnent l'acidité qu'exige un beurre de crustacé, et l'huile d'olive signe une méthode méridionale, si atlantique que soit l'animal. La chair passe en une minute : elle sort pendant que la sauce réduit et ne revient que pour se réchauffer."},
ingredients:["lobster","corail-de-homard","tomato","shallot","garlic","cognac","olive-oil","butter","tarragon","chili","parsley"],
techniques:["concasser","saisir","flamber","deglacer","mijoter","reduction","passer-au-chinois","monter-au-beurre"],
wines:[{appellation:"Chablis premier cru (Chardonnay)",style:"Dry, mineral, high acidity, little or no oak.",band:3,why:{en:"Acidity against the butter and coral; no tannin, because tannin clashes with the iodine of shellfish.",fr:"L'acidité contre le beurre et le corail ; pas de tanin, qui heurte l'iode du crustacé."}},{appellation:"Côtes de Provence rosé (Grenache, Cinsault)",style:"Dry, pale, low tannin, moderate acidity.",band:2,why:{en:"Low tannin with shellfish, and enough acidity to match the tomato already in the sauce.",fr:"Peu de tanin avec le crustacé, et assez d'acidité pour répondre à la tomate de la sauce."}},{appellation:"Côtes du Rhône blanc (Marsanne, Roussanne, Grenache blanc)",style:"Dry, broad, low acidity, bitter finish.",band:2,why:{en:"The body carries a heavily reduced sauce that a lean, sharp wine would leave standing apart.",fr:"La matière soutient une sauce très réduite qu'un vin maigre et vif laisserait à part."}}]},

{id:"jambon-persille-de-bourgogne",group:"charcuterie",name:{en:"Parslied ham in aspic",fr:"Jambon persillé de Bourgogne"},
region:{en:"Bourgogne, particularly the Côte-d’Or and Beaune",fr:"Bourgogne, en particulier la Côte-d’Or et Beaune"},era:{en:"Documented in Bourgogne since the 14th century as the Easter preparation of the winter’s salted ham",fr:"Documenté en Bourgogne depuis le XIVe siècle, préparation pascale du jambon salé de l’hiver"},
summary:{en:"Salted ham hock cooked in an aromatic broth, broken into coarse pieces and set in a parsley-loaded jelly made from trotters and rind. It reads as a terrine but is built the opposite way: the jelly is the binder and there is no forcemeat at all.",
fr:"Jarret de porc salé cuit dans un bouillon aromatique, cassé en gros morceaux et pris dans une gelée chargée de persil, montée sur pieds et couennes. Cela se lit comme une terrine mais se construit à l'envers : la gelée est le liant, et il n'y a aucune farce."},
balance:{en:"Everything depends on collagen: trotters and rind release the gelatin that sets the mould, and if the broth is not reduced enough the slice will not hold, while too much reduction gives a rubbery jelly that seals the mouth. The ham is salty by construction, so the jelly is acidified with vinegar and white wine — acid both preserves and stops the whole thing tasting of nothing but salt and fat. Parsley is not decoration: raw, chopped, and folded in cold, it supplies bitterness and a green freshness that the boiled meat has lost. The dish should be cut thick and eaten cold enough for the jelly to be firm but not straight from the fridge, where cold mutes salt and the acidity disappears.",
fr:"Tout dépend du collagène : les pieds et les couennes libèrent la gélatine qui fait prendre le moule, et si le bouillon n'est pas assez réduit la tranche ne tiendra pas, tandis qu'une réduction excessive donne une gelée caoutchouteuse qui colle la bouche. Le jambon est salé par construction : on acidifie donc la gelée au vinaigre et au vin blanc — l'acide conserve et empêche l'ensemble de ne goûter que le sel et le gras. Le persil n'est pas un décor : cru, haché, incorporé à froid, il apporte l'amertume et la fraîcheur végétale que la viande pochée a perdues. On tranche épais et on sert assez froid pour que la gelée tienne, mais pas sortant du réfrigérateur, où le froid étouffe le sel et fait disparaître l'acidité."},
ingredients:["jarret-de-porc","pied-de-porc","couenne","parsley","tarragon","shallot","garlic","white-wine-vinegar","carrot","bay-leaf","black-pepper","salt"],
techniques:["salaison","blanchir","mijoter","depouiller","clarifier","chemiser","gelee","refroidissement-rapide"],
wines:[{appellation:"Bourgogne Aligoté",style:"dry white, high acidity, lean body",band:1,why:{en:"High acidity matches the vinegar already in the jelly rather than being flattened by it.",fr:"L'acidité élevée répond au vinaigre déjà présent dans la gelée au lieu d'être écrasée par lui."}},{appellation:"Mâcon-Villages, chardonnay",style:"dry white, moderate acidity, unoaked",band:2,why:{en:"Unoaked, so nothing competes with the parsley; enough weight for the salt of the cured ham.",fr:"Sans bois, rien ne concurrence le persil ; assez de matière pour le sel du jambon salé."}},{appellation:"Marsannay rosé, pinot noir",style:"dry rosé, light body, red-fruit aroma, no perceptible tannin",band:2,why:{en:"No tannin, which would clash with the gelatin; acidity handles the fat of the rind.",fr:"Aucun tanin, qui heurterait la gélatine ; l'acidité prend en charge le gras de la couenne."}}]},

{id:"kimchi-jjigae",group:"monde",name:{en:"Kimchi stew",fr:"Kimchi jjigae"},
region:{en:"Korea",fr:"Corée"},era:{en:"Joseon era, after chilli arrived",fr:"Époque Joseon, après l’arrivée du piment"},
summary:{en:"A stew built on kimchi that has fermented past the point of being eaten raw, simmered with pork belly, tofu and a stock of dried anchovy and kombu. It exists because sour kimchi has to go somewhere, and heat is what makes it usable again.",
fr:"Un ragoût monté sur un kimchi fermenté au-delà du point où on le mange cru, mijoté avec de la poitrine de porc, du tofu et un bouillon d'anchois séchés et de kombu. Il existe parce qu'il faut bien utiliser le kimchi devenu acide, et que la cuisson est ce qui le rend de nouveau utilisable."},
balance:{en:"Lactic acid is the axis of the dish: the kimchi is deliberately over-fermented, and that acidity is what cuts the fat of the pork belly. The kimchi is fried first in the rendered fat — heat rounds off the raw acidity and pulls the pigment of the gochugaru into the oil, which is where the colour comes from. Doenjang and fish sauce bring glutamate, while the tofu is a neutral body that takes up stock without adding anything. Plain rice is not a side dish but part of the construction: it is the starch that dilutes the salt, the heat and the acid, and without it the stew is too concentrated to eat on its own.",
fr:"L'acide lactique est l'axe du plat : le kimchi est volontairement trop fermenté, et cette acidité est ce qui coupe le gras de la poitrine de porc. On fait d'abord revenir le kimchi dans le gras fondu — la chaleur arrondit l'acidité brute et fait passer le pigment du gochugaru dans l'huile, d'où vient la couleur. Le doenjang et la sauce de poisson apportent le glutamate, le tofu apporte un corps neutre qui absorbe le bouillon sans rien ajouter. Le riz blanc n'est pas un accompagnement mais une pièce de la construction : c'est l'amidon qui dilue le sel, le piquant et l'acide, et sans lui le ragoût est trop concentré pour être mangé seul."},
ingredients:["kimchi","pork-belly","silken-tofu","gochugaru","gochujang","doenjang","garlic","spring-onion","onion","myeolchi-aekjeot","niboshi","kombu","rice","sesame-oil"],
techniques:["lacto-fermentation","rissoler","infusion-a-froid","mijoter","reduction"],
wines:[{appellation:"Alsace, riesling demi-sec",style:"blanc, sucre résiduel modéré, acidité élevée",band:2,why:{en:"Residual sugar lowers the perceived heat of the capsaicin while the acidity handles the pork fat.",fr:"Le sucre résiduel abaisse la perception du piquant de la capsaïcine tandis que l'acidité reprend le gras de porc."}},{appellation:"Beaujolais, gamay",style:"rouge, tanin faible, acidité élevée, servi frais",band:1,why:{en:"Low tannin, because tannin amplifies chilli heat; served cool, its acidity meets the lactic acid of the kimchi.",fr:"Peu de tanin, parce que le tanin amplifie le piquant du piment ; servi frais, son acidité rejoint l'acide lactique du kimchi."}},{appellation:"Cidre de Bretagne brut",style:"effervescent, acidité malique, alcool faible, peu de sucre",band:1,why:{en:"Carbonation and malic acid work on the fat, and the low alcohol matters because alcohol increases the burn of capsaicin.",fr:"L'effervescence et l'acide malique travaillent le gras, et l'alcool faible compte parce que l'alcool augmente la brûlure de la capsaïcine."}}]},

{id:"kouign-amann",group:"patisserie",name:{en:"Kouign-amann",fr:"Kouign-amann"},
region:{en:"Douarnenez, Finistère",fr:"Douarnenez, Finistère"},era:{en:"Around 1860",fr:"Vers 1860"},
summary:{en:"A leavened dough laminated with salted butter and sugar, baked until the sugar runs out and caramelises around it. It comes from Douarnenez in the 1860s and is closer to bread than to puff pastry.",
fr:"Pâte levée feuilletée au beurre demi-sel et au sucre, cuite jusqu'à ce que le sucre s'échappe et caramélise tout autour. Né à Douarnenez dans les années 1860, il tient plus du pain que du feuilletage."},
balance:{en:"It is a laminated dough whose turns fold in sugar along with the butter: each turn forms a layer of sugar that melts, runs towards the tin and caramelises against the metal. The dough is leavened, unlike classic puff pastry, which gives the interior a bread-like chew under a crisp shell. Salted butter is not a regional flourish but a structural piece: the salt is the only counterweight to a very large quantity of sugar, and without it the caramel reads only as sweetness. Baking must run long enough to take the sugar to true caramel — the bitterness that develops is what makes the cake edible in quantity rather than cloying.",
fr:"C'est une pâte feuilletée dont le tourage incorpore le sucre avec le beurre : à chaque tour se forme une couche de sucre qui fond, coule vers le moule et caramélise au contact du métal. La pâte est levée, contrairement au feuilletage classique, ce qui donne à l'intérieur une mâche de pain sous la coque croustillante. Le beurre demi-sel n'est pas un ornement régional mais une pièce de structure : le sel est le seul contrepoids à une très grande quantité de sucre, et sans lui le caramel ne se lit que comme du sucré. La cuisson doit être assez longue pour mener le sucre au vrai caramel — l'amertume qui s'y développe est ce qui rend le gâteau mangeable en quantité plutôt qu'écœurant."},
ingredients:["flour-t45","beurre-demi-sel","sugar","yeast","fleur-de-sel-guerande"],
techniques:["detrempe","tourage","abaisser","foncer","dorer"],
wines:[{appellation:"Cidre de Cornouaille (Bretagne)",style:"sparkling cider, off-dry, apple acidity, tannic bitterness",band:2,why:{en:"Acidity and tannic bitterness cut the butter, while the residual sugar stops the pastry from making the cider taste sour.",fr:"L'acidité et l'amertume tannique coupent le beurre, tandis que le sucre résiduel empêche la pâtisserie de faire paraître le cidre acide."}},{appellation:"Coteaux du Layon (Loire, chenin)",style:"sweet white, high acidity, botrytis notes",band:3,why:{en:"The wine's sugar must exceed the pastry's or it reads thin, and the acidity carries the caramel.",fr:"Le sucre du vin doit dépasser celui de la pâtisserie, sinon il paraît maigre, et l'acidité porte le caramel."}},{appellation:"Thé noir de Ceylan, sans sucre",style:"unsweetened black tea, tannic, served hot",band:1,why:{en:"Tannin binds the butter fat, and the absence of sugar avoids doubling the caramel.",fr:"Le tanin se lie au gras du beurre, et l'absence de sucre évite de doubler le caramel."}}]},

{id:"mille-feuille",group:"patisserie",name:{en:"Mille-feuille",fr:"Mille-feuille"},
region:{en:"Paris",fr:"Paris"},era:{en:"Modern form fixed in the 19th century, puff pastry and crème pâtissière attributed to Carême",fr:"Forme moderne fixée au XIXe siècle, feuilletage et crème pâtissière attribués à Carême"},
summary:{en:"Three sheets of puff pastry, baked flat and caramelised, alternating with two layers of pastry cream, finished with fondant marbled with chocolate. Everything rests on the pastry staying crisp against a wet filling.",
fr:"Trois abaisses de feuilletage cuites à plat et caramélisées, alternées avec deux couches de crème pâtissière, finies d'un fondant marbré au chocolat. Tout repose sur un feuilletage qui reste croustillant au contact d'une garniture humide."},
balance:{en:"Puff pastry is layers of dough separated by butter; the water in the butter turns to steam and pushes the layers apart. Baked under a weight and dusted with sugar at the end, the surfaces caramelise and become water-resistant, which is the only thing holding back the moisture of the cream. The pastry cream must therefore be tight — bound with starch and cooked out properly — because a slack cream soaks the leaves within the hour. The lesson is general: whenever crisp meets wet, either seal the crisp element or assemble at the last moment.",
fr:"Le feuilletage, ce sont des couches de détrempe séparées par du beurre ; l'eau du beurre se transforme en vapeur et écarte les couches. Cuit sous un poids puis saupoudré de sucre en fin de cuisson, il caramélise en surface et devient imperméable, ce qui est la seule barrière contre l'humidité de la crème. La crème pâtissière doit donc être serrée — liée à l'amidon et bien cuite — car une crème lâche détrempe les abaisses en une heure. La leçon est générale : quand le croustillant rencontre l'humide, on imperméabilise ou on monte au dernier moment."},
ingredients:["flour-t45","laminating-butter","salt","cream","egg","sugar","cornstarch","vanilla","icing-sugar","dark-chocolate"],
techniques:["detrempe","tourage","abaisser","cuire-a-blanc","creme-patissiere","vanner","glacer"],
wines:[{appellation:"Champagne demi-sec",style:"Effervescent, dosage 32 à 50 g/l de sucre, acidité élevée",band:3,why:{en:"The bubble and the acidity strip the butter of the pastry between mouthfuls; the dosage keeps the wine from reading acid against the sugar of the cream.",fr:"La bulle et l'acidité décapent le beurre du feuilletage entre deux bouchées ; le dosage empêche le vin de paraître acide face au sucre de la crème."}},{appellation:"Vouvray demi-sec, chenin blanc",style:"Sucre résiduel modéré, acidité tartrique élevée, notes de pomme et de tilleul",band:2,why:{en:"Chenin holds high acidity alongside its sugar, so it can meet both the fat of the pastry and the sweetness of the cream at once.",fr:"Le chenin porte une acidité élevée en même temps que son sucre, ce qui lui permet de répondre à la fois au gras du feuilletage et au sucre de la crème."}},{appellation:"Thé noir de Darjeeling, seconde récolte",style:"Tanin modéré, sans sucre, notes de fruit à noyau",band:1,why:{en:"Tannin binds the butter of the pastry and rinses the palate, and the absence of sugar leaves the pastry cream to carry the sweetness alone.",fr:"Le tanin fixe le beurre du feuilletage et rince le palais, et l'absence de sucre laisse la crème pâtissière porter seule le sucré."}}]},

{id:"mole-poblano",group:"monde",name:{en:"Mole poblano",fr:"Mole poblano"},
region:{en:"Puebla, Mexico",fr:"Puebla, Mexique"},era:{en:"Late 17th century",fr:"Fin du XVIIe siècle"},
summary:{en:"A sauce of several dried chillies toasted and soaked, ground with fried nuts, seeds, spices and a little chocolate, then fried again in lard and simmered over poached turkey. Convent tradition in Puebla claims it for the late seventeenth century; its base is the pre-Hispanic mōlli.",
fr:"Une sauce de plusieurs piments secs grillés et trempés, broyés avec des fruits secs frits, des graines, des épices et un peu de chocolat, puis refrits au saindoux et mijotés sur une dinde pochée. La tradition conventuelle de Puebla la situe à la fin du XVIIe siècle ; sa base est le mōlli préhispanique."},
balance:{en:"Each chilli does a different job — mulato for its raisin and cocoa depth, ancho for sweetness, pasilla for bitterness, chipotle for smoke and heat. Toasting is the step that decides the dish: a burnt chilli gives a bitterness no amount of sugar corrects afterwards. Fried and ground almonds and sesame provide the body and the emulsion, while the chocolate and the sugar are there to hold the bitterness of the toasted chillies and spices, not to sweeten. The blended sauce is then fried in lard, and it is that second cooking that takes it from a raw paste to a smooth, glossy sauce.",
fr:"Chaque piment fait un travail différent : le mulato pour ses notes de raisin sec et de cacao, l'ancho pour le sucre, le pasilla pour l'amertume, le chipotle pour le fumé et le piquant. Le grillage est l'étape qui décide du plat : un piment brûlé donne une amertume qu'aucun sucre ne rattrape ensuite. Les amandes et le sésame frits puis broyés font le corps et l'émulsion, tandis que le chocolat et le sucre sont là pour tenir l'amertume des piments grillés et des épices, pas pour sucrer. La sauce mixée est ensuite frite au saindoux, et c'est cette seconde cuisson qui la fait passer d'une pâte crue à une sauce lisse et brillante."},
ingredients:["chile-mulato","ancho-chilli","chile-pasilla","chipotle","turkey","dark-chocolate","almond","sesame","raisin","cinnamon","clove","black-pepper","tomatillo","lard"],
techniques:["griller","maceration","frire","passer-au-chinois","pocher","mijoter","reduction"],
wines:[{appellation:"Banyuls, vin doux naturel",style:"rouge muté, sucre résiduel élevé, notes oxydatives",band:3,why:{en:"Residual sugar buffers the capsaicin, and the oxidative notes meet the cocoa and the toasted seeds.",fr:"Le sucre résiduel tamponne la capsaïcine, et les notes oxydatives rejoignent le cacao et les graines grillées."}},{appellation:"Rioja crianza, tempranillo",style:"rouge, tanin modéré, élevage en fût, acidité moyenne",band:2,why:{en:"Moderate tannin and oak vanillin against the toasted chillies, with acidity for the lard.",fr:"Un tanin modéré et la vanilline du fût face aux piments grillés, avec l'acidité pour le saindoux."}},{appellation:"Infusion d'hibiscus (agua de jamaica), sans alcool",style:"infusion acide, sucrée, servie froide, sans alcool",band:1,why:{en:"High acidity cuts the fat of a sauce that carries almost no acid of its own.",fr:"L'acidité élevée coupe le gras d'une sauce qui ne porte presque aucun acide."}}]},

{id:"moussaka",group:"monde",name:{en:"Moussaka",fr:"Moussaka"},
region:{en:"Greece",fr:"Grèce"},era:{en:"1920s",fr:"Années 1920"},
summary:{en:"Aubergine, minced lamb cooked with tomato and warm spice, and a béchamel bound with egg, layered and baked until the top is browned. The béchamel version was fixed in the 1920s by Nikolaos Tselementes, who set out to bring Greek cooking closer to French practice.",
fr:"Aubergine, hachis d'agneau cuit à la tomate et aux épices chaudes, et une béchamel liée à l'œuf, montés en couches et passés au four jusqu'à coloration. La version à la béchamel a été fixée dans les années 1920 par Nikolaos Tselementes, qui voulait rapprocher la cuisine grecque de la pratique française."},
balance:{en:"Aubergine is a sponge: its open flesh drinks whatever oil it is given, so it is salted first to draw out water and tighten the cells, which limits absorption — otherwise all three layers drown in fat. The lamb brings fat and salt, the tomato the acid that cuts it, the cinnamon and allspice a warm bitterness that stands as the aromatic counterweight. The béchamel bound with egg is not decoration: it sets in the oven and gives the structure that lets a portion be cut clean, and its gratinated crust brings Maillard bitterness against the sugar of the cooked aubergine. The dish is rested before cutting, or the layers slide.",
fr:"L'aubergine est une éponge : sa chair alvéolée boit toute l'huile qu'on lui donne, on la dégorge donc au sel pour faire sortir l'eau et resserrer les cellules, ce qui limite l'absorption — sinon les trois couches se noient dans le gras. L'agneau apporte le gras et le sel, la tomate l'acidité qui le tranche, la cannelle et le quatre-épices une amertume chaude qui tient le contrepoint aromatique. La béchamel liée à l'œuf n'est pas un décor : elle prend au four et donne la structure qui permet de couper une part nette, et sa croûte gratinée apporte l'amertume de Maillard face au sucre de l'aubergine cuite. Le plat repose avant d'être coupé, sinon les couches glissent."},
ingredients:["eggplant","lamb","onion","garlic","tomato","cinnamon","allspice","olive-oil","butter","flour-t55","cream","egg","nutmeg","graviera"],
techniques:["degorger","rissoler","roux-blanc","liaison-a-l-oeuf","gratiner","reduction","ciseler"],
wines:[{appellation:"Naoussa, xinomavro",style:"rouge, acidité élevée, tanin ferme",band:2,why:{en:"High acidity and firm tannin against lamb fat; the tannin binds to the meat protein and reads softer for it.",fr:"Acidité élevée et tanin ferme face au gras d'agneau ; le tanin se lie aux protéines de la viande et s'en trouve assoupli."}},{appellation:"Némée, agiorgitiko",style:"rouge, tanin souple, fruit rouge mûr",band:2,why:{en:"Softer tannin for a dish whose spicing is warm rather than sharp; the acidity still handles the béchamel.",fr:"Un tanin plus souple pour un plat dont les épices sont chaudes plutôt que vives ; l'acidité reprend la béchamel."}},{appellation:"Santorin, assyrtiko",style:"blanc sec, acidité très élevée, salin",band:3,why:{en:"Very high acidity and no oak: it cuts the béchamel where a rounder white would sit on top of it.",fr:"Acidité très élevée et pas de bois : il découpe la béchamel là où un blanc plus rond resterait posé dessus."}}]},

{id:"museau-vinaigrette",group:"charcuterie",name:{en:"Ox muzzle salad with vinaigrette",fr:"Museau vinaigrette"},
region:{en:"Charcuteries across France; a fixture of the traiteur counter",fr:"Charcuteries de toute la France ; incontournable du comptoir traiteur"},era:{en:"Traditional offal charcuterie; a standard bistro and delicatessen item through the 20th century",fr:"Charcuterie d’abats traditionnelle ; classique des bistrots et des traiteurs tout au long du XXe siècle"},
summary:{en:"Beef or pork muzzle poached in broth until tender, sliced thin, and dressed cold with vinaigrette, onion, gherkin and parsley. It is the cheapest lesson in what acid does to gelatin.",
fr:"Museau de bœuf ou de porc poché au bouillon jusqu'à tendreté, tranché fin, assaisonné froid à la vinaigrette avec oignon, cornichon et persil. C'est la leçon la moins chère sur ce que l'acide fait à la gélatine."},
balance:{en:"Muzzle is connective tissue and nothing else, so long poaching is not optional: undercooked it is rubber, and correctly cooked it becomes translucent and sticky on the lips. That stickiness is the problem the dressing solves — a vinaigrette made sharper than usual, roughly one part vinegar to three of oil rather than four, because gelatin dulls acidity on contact. Slicing thin matters as much as the seasoning: a thick piece of muzzle is a mouthful of gum, a thin one carries dressing on both faces and eats cleanly. Raw onion and gherkin are there for crunch as much as for taste, since the meat itself offers no resistance at all, and the salad wants an hour in the dressing so the acid can penetrate the gelatin rather than sit on it.",
fr:"Le museau n'est que du tissu conjonctif : le long pochage n'est donc pas facultatif — insuffisamment cuit c'est du caoutchouc, correctement cuit il devient translucide et collant aux lèvres. Ce collant est le problème que règle l'assaisonnement : une vinaigrette montée plus acide que d'usage, environ un volume de vinaigre pour trois d'huile plutôt que quatre, car la gélatine éteint l'acidité au contact. Trancher fin compte autant que l'assaisonnement : un morceau épais est une bouchée de gomme, un morceau fin porte la vinaigrette sur ses deux faces et se mange net. L'oignon cru et le cornichon sont là pour le croquant autant que pour le goût, la viande n'offrant aucune résistance, et la salade demande une heure dans son assaisonnement pour que l'acide pénètre la gélatine au lieu de rester dessus."},
ingredients:["museau","red-onion","cornichon","shallot","parsley","red-wine-vinegar","dijon-mustard","sunflower-oil","bay-leaf","black-pepper"],
techniques:["pocher","mijoter","emincer","ciseler","emulsion-froide","mariner","refroidissement-rapide"],
wines:[{appellation:"Beaujolais, gamay",style:"light tannin, high acidity, red fruit, served cool",band:1,why:{en:"Served cool its acidity matches the vinaigrette; low tannin, which would otherwise add dryness to gelatin.",fr:"Servi frais, son acidité se cale sur la vinaigrette ; tanin faible, qui ajouterait sinon de la sécheresse à la gélatine."}},{appellation:"Touraine, gamay",style:"light red, low tannin, high acidity",band:1,why:{en:"High acidity is what allows a wine to stand beside a vinegar dressing without tasting hollow.",fr:"Une acidité élevée est ce qui permet à un vin de tenir à côté d'une vinaigrette sans paraître creux."}},{appellation:"Muscadet Sèvre et Maine, melon de Bourgogne",style:"dry white, high acidity, saline, light",band:1,why:{en:"Salinity and acidity work on the fat of the muzzle; no oak to blur a dish built on sharpness.",fr:"Salinité et acidité travaillent le gras du museau ; aucun bois ne brouille un plat bâti sur la vivacité."}}]},

{id:"navarin-d-agneau",group:"monde",name:{en:"Lamb navarin",fr:"Navarin d'agneau"},
region:{en:"French repertoire; the printanier version follows the spring vegetable season",fr:"Répertoire français ; la version printanière suit la saison des légumes de printemps"},era:{en:"19th century; the name is usually linked to the naval battle of Navarino, 20 October 1827, though the attribution is disputed",fr:"XIXe siècle ; le nom est ordinairement rattaché à la bataille navale de Navarin, 20 octobre 1827, attribution discutée"},
summary:{en:"A brown lamb stew, the meat seared with a pinch of sugar, dusted with flour and braised, then finished with vegetables cooked separately. In the printanier version those vegetables are the spring crop — turnips, carrots, peas, beans, new potatoes.",
fr:"Ragoût brun d'agneau : la viande est saisie avec une pincée de sucre, singée puis braisée, et finie avec des légumes cuits à part. Dans la version printanière, ces légumes sont ceux du printemps — navets, carottes, petits pois, haricots verts, pommes nouvelles."},
balance:{en:"The pinch of sugar at the searing stage is not seasoning, it is a caramel: it deepens the colour and gives the sauce a bitter-sweet base that lamb fat needs. Lamb is strongly flavoured and its fat coats the palate heavily, so the counterweights are acid from the tomato and garlic and freshness from vegetables that were never in the braising liquid. Cooking them apart and glazing them is the whole discipline of the dish — put them in with the meat and they take on the fat, lose their colour and turn the plate into one uniform brown texture. Each vegetable has its own cooking time; the plate is assembled at the end, not simmered into agreement.",
fr:"La pincée de sucre à la saisie n'est pas un assaisonnement, c'est un caramel : elle fonce la coloration et donne à la sauce une base douce-amère dont le gras d'agneau a besoin. L'agneau a un goût marqué et un gras qui nappe lourdement le palais : les contrepoids sont l'acide de la tomate et de l'ail, et la fraîcheur de légumes qui ne sont jamais passés dans le mouillement. Les cuire à part et les glacer est toute la discipline du plat — mis avec la viande, ils prennent le gras, perdent leur couleur et ramènent l'assiette à une seule texture brune. Chaque légume a son temps de cuisson ; l'assiette se monte à la fin, elle ne se mijote pas jusqu'à l'accord."},
ingredients:["epaule-agneau","collier-agneau","carrot","turnip","pearl-onion","pea","green-bean","ratte-potato","tomato","garlic","bay-leaf","thyme","sugar","flour-t55"],
techniques:["parer","rissoler","singer","deglacer","braiser","tourner","glacer-a-brun","cuire-a-l-anglaise"],
wines:[{appellation:"Saumur-Champigny, cabernet franc",style:"light tannin, high acidity, red fruit and vegetal notes",band:2,why:{en:"The acidity works on lamb fat; low tannin, since the sauce is lightly bound and offers little gelatin to bind it.",fr:"L'acidité travaille le gras d'agneau ; peu de tanin, la sauce étant peu liée et offrant peu de gélatine pour le fixer."}},{appellation:"Côtes du Rhône, grenache and syrah",style:"medium tannin, dry, peppery notes",band:1,why:{en:"The peppery register runs with the thyme and bay; medium tannin matches the browned surface of the meat.",fr:"Le registre poivré suit le thym et le laurier ; un tanin moyen répond à la surface colorée de la viande."}},{appellation:"Coteaux d'Aix-en-Provence, rosé",style:"dry, high acidity, light body, no tannin",band:1,why:{en:"No tannin at all, which leaves the spring vegetables legible; the acidity handles the fat.",fr:"Aucun tanin, ce qui laisse les légumes de printemps lisibles ; l'acidité prend le gras."}}]},

{id:"opera",group:"patisserie",name:{en:"Opéra",fr:"Opéra"},
region:{en:"Paris",fr:"Paris"},era:{en:"1955, at Dalloyau; authorship credited to the house by Le Monde in 1988",fr:"1955, chez Dalloyau ; paternité attribuée à la maison par Le Monde en 1988"},
summary:{en:"Thin almond sponge soaked in coffee syrup, layered with coffee buttercream and chocolate ganache, glazed with chocolate. It was designed so that a single bite contains every layer.",
fr:"De fines feuilles de biscuit joconde imbibées de sirop de café, alternées avec une crème au beurre au café et une ganache au chocolat, glacées au chocolat. Il a été conçu pour qu'une seule bouchée contienne toutes les couches."},
balance:{en:"The construction is a stack of thin layers rather than thick ones, because the point is to have the whole formula in one spoonful — geometry doing the work of flavour. Coffee and dark chocolate are both bitter, and that shared bitterness is what allows the very high sugar of the buttercream and the glaze to pass. Joconde sponge contains almond flour and little gluten, so it stays supple and soaks the coffee syrup without turning to paste. The cake is served cold and cut with a hot knife: at room temperature the buttercream softens and the layers stop reading as separate things.",
fr:"La construction empile des couches fines plutôt qu'épaisses, parce que le but est d'avoir toute la formule dans une cuillère — la géométrie fait ici le travail du goût. Le café et le chocolat noir sont tous deux amers, et c'est cette amertume commune qui fait passer le sucre très élevé de la crème au beurre et du glaçage. Le biscuit joconde contient de la poudre d'amande et peu de gluten : il reste souple et boit le sirop de café sans devenir pâteux. Le gâteau se sert froid et se coupe au couteau chaud : à température ambiante la crème au beurre se relâche et les couches cessent de se lire séparément."},
ingredients:["almond-flour","icing-sugar","egg","flour-t55","butter","sugar","coffee","coffee-extract","dark-chocolate","cream","cocoa-butter","feuille-d-or"],
techniques:["monter-les-blancs","pate-a-bombe","cuisson-du-sucre","monter-au-beurre","ganache","temperage-du-chocolat","masquer","glacer"],
wines:[{appellation:"Banyuls grand cru, grenache noir",style:"Muté, élevage oxydatif, sucre résiduel élevé, tanin fondu",band:3,why:{en:"The residual sugar reaches the level of the glaze so the chocolate does not strip the wine, and the oxidative notes align with the roasted coffee.",fr:"Le sucre résiduel atteint le niveau du glaçage, donc le chocolat ne décharne pas le vin, et les notes oxydatives rejoignent le café torréfié."}},{appellation:"Porto tawny, élevage prolongé en fût",style:"Muté, oxydatif, sucre élevé, tanin déjà fondu, notes de noix",band:2,why:{en:"Long cask ageing has already resolved the tannin, which matters because the tannin of dark chocolate and that of a young wine add up and dry the palate.",fr:"Le long élevage en fût a déjà fondu le tanin, ce qui compte car le tanin du chocolat noir et celui d'un vin jeune s'additionnent et assèchent le palais."}},{appellation:"Café, espresso arabica torréfaction moyenne",style:"Sans sucre, amertume marquée, corps épais",band:1,why:{en:"It repeats the coffee of the syrup and its bitterness works directly against the sugar of the buttercream, with no added sweetness of its own.",fr:"Il reprend le café du sirop et son amertume agit directement contre le sucre de la crème au beurre, sans apporter de sucre supplémentaire."}}]},

{id:"osso-buco-a-la-milanaise",group:"monde",name:{en:"Osso buco, Milanese style",fr:"Osso buco à la milanaise"},
region:{en:"Milan, Lombardy",fr:"Milan, Lombardie"},era:{en:"19th century",fr:"XIXe siècle"},
summary:{en:"Cross-cut veal shank, bone and marrow included, braised for hours with aromatics and tomato until the sauce coats. It is finished raw, with gremolata: lemon zest, garlic and parsley chopped together and scattered off the heat.",
fr:"Un jarret de veau tranché en travers, os et moelle compris, braisé plusieurs heures avec sa garniture aromatique et de la tomate jusqu'à ce que la sauce nappe. Il se termine à cru, à la gremolata : zeste de citron, ail et persil hachés ensemble et jetés hors du feu."},
balance:{en:"The shank is a working muscle, long on collagen, and it turns tender only after hours of gentle cooking, the time the collagen needs to become gelatin and give the sauce its coating power. Tomato and wine supply the acid that cuts the marrow fat; without it the sauce stays heavy in the mouth. The gremolata goes on raw at the last moment — the zest, garlic and parsley have not cooked, they keep their volatile compounds and open up a dish that has just braised for three hours. It is served on saffron risotto because the rice starch takes up the sauce the meat cannot hold.",
fr:"Le jarret est un muscle de travail, long en collagène : il ne devient tendre qu'après plusieurs heures de cuisson douce, le temps que le collagène se transforme en gélatine et donne à la sauce son pouvoir nappant. La tomate et le vin apportent l'acidité qui découpe le gras de la moelle ; sans elle la sauce reste lourde en bouche. La gremolata arrive crue au dernier moment : le zeste, l'ail et le persil n'ont pas cuit, ils gardent leurs composés volatils et ouvrent un plat qui vient de mijoter trois heures. On le sert sur un risotto au safran parce que l'amidon du riz reprend la sauce que la viande ne retient pas."},
ingredients:["veau-sous-la-mere","bone-marrow","onion","carrot","celery","butter","san-marzano-tomato","lemon","parsley","garlic","flour-t55","bay-leaf"],
techniques:["ficeler","rissoler","deglacer","braiser","mijoter","reduction","hacher"],
wines:[{appellation:"Barbera d'Asti, Piémont",style:"rouge, acidité élevée, tanin faible",band:2,why:{en:"High acidity answers the gelatin and the marrow fat, and the low tannin avoids a clash with the raw lemon zest of the gremolata.",fr:"L'acidité élevée répond à la gélatine et au gras de la moelle, et le tanin faible évite le heurt avec le zeste de citron cru de la gremolata."}},{appellation:"Barbaresco, nebbiolo",style:"rouge, tanin marqué, acidité élevée",band:4,why:{en:"Tannin binds to the protein and gelatin of the braise, which lowers its astringency.",fr:"Le tanin se lie aux protéines et à la gélatine du braisé, ce qui abaisse son astringence."}},{appellation:"Soave Classico, garganega",style:"blanc sec, sans élevage sous bois, acidité moyenne à élevée",band:2,why:{en:"Acidity without tannin: veal offers little protein for tannin to bind, and the raw zest sits better against a white.",fr:"De l'acidité sans tanin : le veau offre peu de protéines à lier, et le zeste cru se tient mieux face à un blanc."}}]},

{id:"paella-valenciana",group:"monde",name:{en:"Valencian paella",fr:"Paella valenciana"},
region:{en:"Albufera, Valencia",fr:"Albufera, Valence"},era:{en:"Mid-19th century",fr:"Milieu du XIXe siècle"},
summary:{en:"Rice cooked flat and unstirred in a wide shallow pan with chicken, rabbit, two beans, tomato, saffron and rosemary. It came out of the farmland around the Albufera lagoon, and the protected recipe holds to ten ingredients.",
fr:"Un riz cuit à plat, sans être remué, dans une poêle large et basse avec poulet, lapin, deux haricots, tomate, safran et romarin. Il vient des terres agricoles autour de l'Albufera, et la recette protégée s'en tient à dix ingrédients."},
balance:{en:"It is the exact opposite of risotto: the rice is never stirred. It cooks in a thin layer in a stock whose level drops by evaporation, keeps its starch inside the grain, and the grains stay separate. Fat comes from the chicken and rabbit seared first in the oil, the tomato sofrito brings acid and sugar, the pimentón smoke, the saffron bitterness; the beans, high in starch, thicken the base slightly. At the end the heat is raised: the socarrat, the caramelised layer stuck to the metal, is the only crisp texture in a dish that is otherwise uniformly tender.",
fr:"C'est l'exact contraire du risotto : on ne remue jamais. Le riz cuit en couche mince dans un bouillon dont le niveau baisse par évaporation, il garde son amidon à l'intérieur du grain et les grains restent détachés. Le gras vient du poulet et du lapin saisis d'abord dans l'huile, le sofrito de tomate apporte l'acidité et le sucre, le pimentón le fumé, le safran l'amertume ; les haricots, riches en amidon, épaississent légèrement le fond. En fin de cuisson on pousse le feu : le socarrat, la couche caramélisée collée au métal, est la seule texture croustillante d'un plat par ailleurs uniformément tendre."},
ingredients:["bomba","chicken","rabbit","green-bean","judion","tomato","olive-oil","saffron","pimenton-de-la-vera","rosemary","petit-gris","salt"],
techniques:["rissoler","saisir","mijoter","reduction","fond-blanc"],
wines:[{appellation:"Valencia, merseguera",style:"blanc sec, peu aromatique, acidité moyenne",band:1,why:{en:"Acidity against the oil the rice has absorbed, and a neutral aromatic profile that leaves the saffron and pimentón in place.",fr:"De l'acidité face à l'huile que le riz a absorbée, et un profil aromatique neutre qui laisse le safran et le pimentón en place."}},{appellation:"Utiel-Requena, bobal rosé",style:"rosé sec, acidité moyenne, sans tanin perceptible",band:1,why:{en:"Enough acidity for the fat, and no tannin to work against the saffron.",fr:"Assez d'acidité pour le gras, et pas de tanin pour contrarier le safran."}},{appellation:"Cava, macabeo, xarel·lo et parellada",style:"effervescent, brut, seconde fermentation en bouteille",band:2,why:{en:"Bubbles and acidity clear the fat concentrated in the socarrat.",fr:"Les bulles et l'acidité nettoient le gras concentré dans le socarrat."}}]},

{id:"paris-brest",group:"patisserie",name:{en:"Paris-Brest",fr:"Paris-Brest"},
region:{en:"Maisons-Laffitte, Île-de-France",fr:"Maisons-Laffitte, Île-de-France"},era:{en:"1910, created for the Paris-Brest-Paris cycle race",fr:"1910, créé pour la course cycliste Paris-Brest-Paris"},
summary:{en:"A ring of choux pastry, split and filled with a praline cream, topped with flaked almonds and icing sugar. The shape copies a bicycle wheel; the praline is what the dish is actually about.",
fr:"Une couronne de pâte à choux fendue et garnie d'une crème pralinée, parsemée d'amandes effilées et sucrée au sucre glace. La forme copie une roue de vélo ; le sujet réel du gâteau, c'est le praliné."},
balance:{en:"Praline is caramelised sugar plus roasted nut, so it arrives with both sweetness and the bitterness of the caramel and the roast. The cream is a pastry cream mounted with butter, and the fat of that butter is what carries the praline aroma across the palate — fat is the solvent here, not a garnish. Choux is nearly dry and almost unsweetened, which is why the ring can hold that much rich cream without becoming cloying: the pastry is the ballast. Toasted flaked almonds on top add a second, drier crunch that the cream cannot soften.",
fr:"Le praliné, c'est du sucre caramélisé plus du fruit sec torréfié : il apporte donc à la fois le sucre et l'amertume du caramel et de la torréfaction. La crème est une pâtissière montée au beurre, et c'est le gras de ce beurre qui transporte l'arôme du praliné en bouche — ici le gras est un solvant, pas une garniture. La pâte à choux est presque sèche et à peine sucrée, ce qui permet à la couronne de porter autant de crème sans écœurer : la pâte fait lest. Les amandes effilées torréfiées ajoutent un second croquant, plus sec, que la crème ne peut pas ramollir."},
ingredients:["flour-t55","butter","egg","salt","sugar","cream","praline-paste","piedmont-hazelnut","almond","icing-sugar","cornstarch","vanilla"],
techniques:["pate-a-choux","dorer","creme-patissiere","monter-au-beurre","caramel-a-sec"],
wines:[{appellation:"Maury, grenache noir",style:"Vin doux naturel, sucre résiduel élevé, tanin fondu, notes oxydatives de noix",band:2,why:{en:"The sugar sits at the level of the praline, so the wine does not read dry against it. The oxidative nut notes come from the same reactions as the roasted hazelnut.",fr:"Le sucre se situe au niveau du praliné, donc le vin ne paraît pas sec en face. Les notes oxydatives de fruit sec viennent des mêmes réactions que la noisette torréfiée."}},{appellation:"Rivesaltes ambré, grenache blanc",style:"Muté, élevage oxydatif, notes d'amande grillée et d'orange séchée",band:2,why:{en:"Oxidative ageing produces aldehydes close to those of roasted nut, which places the wine on the same aromatic axis as the filling rather than in opposition to it.",fr:"L'élevage oxydatif produit des aldéhydes proches de ceux du fruit sec torréfié, ce qui place le vin sur le même axe aromatique que la garniture plutôt qu'en opposition."}},{appellation:"Café, arabica lavé d'Éthiopie",style:"Sans sucre, amertume nette, acidité vive",band:1,why:{en:"With no sugar of its own, the bitterness works directly against the butter of the mounted cream and clears it from the palate.",fr:"Sans sucre propre, l'amertume agit directement contre le beurre de la crème montée et le chasse du palais."}}]},

{id:"piperade",group:"france",name:{en:"Piperade",fr:"Piperade"},
region:{en:"Pays Basque and Béarn",fr:"Pays Basque et Béarn"},era:{en:"Shepherds' summer dish, nineteenth century",fr:"Plat d’été des bergers, XIXe siècle"},
summary:{en:"Basque peppers, onion and tomato stewed down at length, then bound with beaten egg stirred to a soft curd. It stands between a vegetable stew and an omelette, and the peppers cook far longer than a cook used to sautéing would expect.",
fr:"Poivrons du Pays basque, oignons et tomates fondus longuement, puis liés à l'œuf battu remué en crème. La piperade tient du ragoût de légumes autant que de l'omelette ; les poivrons y cuisent bien plus longtemps qu'on ne l'imagine."},
balance:{en:"Peppers cooked long enough turn sweet, and tomato is the acid that keeps that sweetness from cloying: the whole dish sits in that ratio. Espelette gives warmth rather than fire, so the seasoning reads as depth and not as burn. The egg goes in off strong heat and sets to a loose curd; its fat rounds the acidity of the tomato and binds a mixture that would otherwise be watery. Cured ham supplies salt and chew, added late so it does not dissolve into the vegetable.",
fr:"Des poivrons cuits assez longtemps deviennent sucrés, et la tomate est l'acide qui empêche ce sucre d'écœurer : tout le plat tient dans ce rapport. Le piment d'Espelette donne de la chaleur plutôt que du feu, si bien que l'assaisonnement se lit comme de la profondeur et non comme une brûlure. L'œuf est incorporé hors du feu vif et prend en crème souple ; son gras arrondit l'acidité de la tomate et lie un mélange qui serait autrement aqueux. Le jambon sec apporte le sel et le mâché, ajouté en fin de cuisson pour ne pas se dissoudre dans le légume."},
ingredients:["gernika-pepper","bell-pepper","tomato","onion","garlic","espelette","olive-oil","egg","jambon-de-bayonne","thyme"],
techniques:["griller","monder","emincer","etuver","mijoter","sauter"],
wines:[{appellation:"Irouléguy blanc (Pays basque, gros et petit manseng)",style:"dry white, high acidity, stone-fruit aroma",band:3,why:{en:"The acidity balances the cooked sweetness of the peppers.",fr:"L'acidité équilibre le sucre de cuisson des poivrons."}},{appellation:"Irouléguy rosé",style:"dry rosé, red fruit, low tannin",band:2,why:{en:"Low tannin, because tannin clashes with egg; enough acidity for the tomato.",fr:"Peu de tanin, car le tanin heurte l'œuf ; assez d'acidité pour la tomate."}},{appellation:"Jurançon sec (Béarn)",style:"dry white, high acidity, citrus",band:2,why:{en:"Citrus acidity cuts the fat of the cured ham.",fr:"L'acidité d'agrume coupe le gras du jambon sec."}}]},

{id:"pot-au-feu",group:"france",name:{en:"Pot-au-feu",fr:"Pot-au-feu"},
region:{en:"All of France; the name first designates the pot itself, hung over the hearth",fr:"Toute la France ; le nom désigne d’abord le pot lui-même, suspendu dans l’âtre"},era:{en:"The term is dated to the 17th century by the Dictionnaire de l’Académie française",fr:"Terme daté du XVIIe siècle par le Dictionnaire de l’Académie française"},
summary:{en:"Several cuts of beef, marrow bones and root vegetables poached for hours in water that is barely trembling, giving a clear broth and boiled meat served together. Everything turns on one decision: the meat goes into cold water, so the flavour moves out into the liquid.",
fr:"Plusieurs morceaux de bœuf, des os à moelle et des légumes racines pochés des heures dans une eau qui frémit à peine, pour donner un bouillon clair et une viande bouillie servis ensemble. Tout tient à une décision : la viande part à l'eau froide, donc le goût passe dans le liquide."},
balance:{en:"Cold water start, slow rise, no boiling: proteins come out gradually and coagulate into a scum that is lifted off, which is the only way the broth stays clear. Start in hot water instead and the surface seizes, the flavour stays in the meat and the broth is thin — the same choice, made in the other direction, is what a roast is for. Boiled meat is by construction low in aroma and high in fat and gelatin, which is why it is never served alone: coarse salt, mustard, cornichons and horseradish supply the salt, acid and pungency the cooking removed. The vegetables go in late and in order of density, or they collapse into the broth and cloud it.",
fr:"Départ à l'eau froide, montée lente, jamais d'ébullition : les protéines sortent progressivement et coagulent en écume qu'on retire, seul moyen de garder le bouillon clair. À l'eau chaude, la surface se saisit, le goût reste dans la viande et le bouillon est maigre — le même choix, pris dans l'autre sens, c'est celui du rôti. Une viande bouillie est par construction peu aromatique, grasse et gélatineuse : on ne la sert jamais seule. Gros sel, moutarde, cornichons et raifort rendent le sel, l'acide et le piquant que la cuisson a emportés. Les légumes entrent tard et par ordre de densité, sinon ils se défont dans le bouillon et le troublent."},
ingredients:["plat-de-cotes","paleron","jarret-de-boeuf","oxtail","bone-marrow","carrot","turnip","leek","celery","onion","clove","black-pepper","cornichon","sel-gris-guerande"],
techniques:["ficeler","blanchir","depouiller","pocher","bouillir","tourner","degorger","clarifier"],
wines:[{appellation:"The pot's own broth, skimmed of fat and strained",style:"clear, saline, gelatinous, no acidity",band:1,why:{en:"Taken first, it clears the palate before the fat of the meat and the marrow; a non-alcoholic option that shares the salt of the dish.",fr:"Pris en premier, il nettoie le palais avant le gras de la viande et de la moelle ; option sans alcool, qui partage le sel du plat."}},{appellation:"Beaujolais, gamay",style:"light tannin, high acidity, low extraction",band:1,why:{en:"Low tannin, because boiled meat has no roasted structure to meet it; the acidity handles the marrow fat.",fr:"Peu de tanin, parce que la viande bouillie n'oppose aucune structure de rôti ; l'acidité prend le gras de la moelle."}},{appellation:"Bourgogne aligoté",style:"dry, high acidity, low aroma",band:1,why:{en:"The high acidity works on the fat and matches the mustard and cornichons served alongside.",fr:"L'acidité élevée travaille le gras et rejoint la moutarde et les cornichons servis à côté."}}]},

{id:"poule-au-pot",group:"france",name:{en:"Stuffed hen in the pot",fr:"Poule au pot"},
region:{en:"Béarn",fr:"Béarn"},era:{en:"Attached to Henri IV, but the sentence about a hen in every pot was first printed in 1664, more than fifty years after his death in 1610",fr:"Attachée à Henri IV, mais la phrase sur la poule au pot n’est imprimée qu’en 1664, plus de cinquante ans après sa mort en 1610"},
summary:{en:"A boiling hen stuffed with ham, bread, egg and garlic, sewn shut and poached with vegetables in its own broth. The stuffing is the point: it cooks inside the bird and takes up everything the lean flesh would otherwise lose.",
fr:"Une poule à bouillir farcie de jambon, de pain, d'œuf et d'ail, cousue et pochée avec les légumes dans son bouillon. La farce est le sujet : elle cuit dans la volaille et récupère tout ce que la chair maigre perdrait autrement."},
balance:{en:"A boiling hen is old, lean and firm, and poaching it strips what little fat and flavour it has into the broth — the stuffing is the engineering answer, a fatty, salty, absorbent mass placed exactly where the juices run. Bread and egg give it the structure to hold and slice, the ham gives salt and cured depth, the garlic gives pungency against the flat sweetness of poached poultry. The broth then goes two ways: it cooks the vegetables and it becomes a white sauce, so nothing is discarded and the whole plate tastes of one thing at different concentrations. A squeeze of acid in the sauce is what keeps that concentration from turning heavy.",
fr:"Une poule à bouillir est vieille, maigre et ferme, et le pochage fait passer dans le bouillon le peu de gras et de goût qu'elle a — la farce est la réponse technique : une masse grasse, salée, absorbante, placée exactement là où les sucs coulent. Le pain et l'œuf lui donnent la tenue pour être tranchée, le jambon apporte le sel et la profondeur du salaison, l'ail le piquant contre la douceur plate d'une volaille pochée. Le bouillon part ensuite dans deux directions : il cuit les légumes et devient une sauce blanche. Rien ne se jette, et toute l'assiette goûte la même chose à des concentrations différentes. Un trait d'acide dans la sauce empêche cette concentration de devenir lourde."},
ingredients:["poule-a-bouillir","jambon-de-bayonne","egg","garlic","parsley","carrot","leek","turnip","onion","clove","cabbage","rice","butter","flour-t55"],
techniques:["habiller","farcir","brider","pocher","depouiller","veloute","liaison-a-l-oeuf","passer-au-chinois"],
wines:[{appellation:"Jurançon sec, gros manseng and petit manseng",style:"dry, high acidity, citrus and stone-fruit notes",band:2,why:{en:"The acidity cuts the fat of the stuffing and the white sauce; a local dry white built on acidity rather than weight.",fr:"L'acidité tranche le gras de la farce et de la sauce blanche ; un blanc sec local construit sur l'acidité, non sur le volume."}},{appellation:"Pacherenc du Vic-Bilh sec",style:"dry, high acidity, medium body",band:2,why:{en:"Dry and firm, because the sauce is already rich; a wine with residual sugar would add to the fat rather than answer it.",fr:"Sec et tendu, parce que la sauce est déjà riche ; un vin à sucre résiduel s'ajouterait au gras au lieu de lui répondre."}},{appellation:"Béarn, tannat and cabernet franc",style:"medium tannin, dry, red fruit",band:2,why:{en:"Moderate tannin meets the cured ham in the stuffing, where the salt softens the tannic impression.",fr:"Un tanin modéré rejoint le jambon de la farce, dont le sel adoucit l'impression tannique."}}]},

{id:"pate-en-croute",group:"charcuterie",name:{en:"Pâté en croûte",fr:"Pâté en croûte"},
region:{en:"Lyon, Bourgogne, Franche-Comté",fr:"Lyon, Bourgogne, Franche-Comté"},era:{en:"Medieval origin as a sealed cooking case; named and fixed in its modern form in the 18th century",fr:"Origine médiévale, comme étui de cuisson scellé ; nommé et fixé dans sa forme moderne au XVIIIe siècle"},
summary:{en:"A seasoned forcemeat of pork, veal and liver baked inside a lined pastry case, then filled with jelly and sliced cold. The crust began as a container and became the dish: it must stay dry and crisp against a moist, fatty filling.",
fr:"Une farce assaisonnée de porc, de veau et de foie cuite dans une pâte foncée en moule, puis coulée à la gelée et tranchée froide. La croûte, d'abord contenant, est devenue le plat : elle doit rester sèche et croustillante contre une farce grasse et humide."},
balance:{en:"Cold flattens seasoning, so the forcemeat is salted and fatted beyond what tastes right hot — taste a poached test quenelle warm and it should read slightly too strong. Fat is not optional: at fridge temperature it is what makes the slice tender rather than crumbly, and the liver brings the bitterness that stops the fat from reading flat. The forcemeat shrinks as it cooks and leaves a gap under the lid; the jelly poured in cold fills it and glues crust to meat, and it must be well seasoned and slightly acidic or it tastes of nothing. The crust does the opposite job: lean, unsweetened, cooked dry, it gives the brittle snap that the soft filling has no way of providing.",
fr:"Le froid écrase l'assaisonnement : la farce est donc salée et grassée au-delà de ce qui paraît juste à chaud — on poche une quenelle témoin, elle doit sembler un peu trop relevée. Le gras n'est pas négociable : à température de réfrigérateur, c'est lui qui rend la tranche fondante au lieu de friable, et le foie apporte l'amertume qui empêche le gras de tourner plat. La farce se rétracte à la cuisson et laisse un vide sous le couvercle ; la gelée coulée froide le comble et soude la croûte à la viande, elle doit être bien assaisonnée et légèrement acide sinon elle ne goûte rien. La croûte fait le travail inverse : maigre, non sucrée, cuite à sec, elle donne le croquant que la farce ne peut pas fournir."},
ingredients:["flour-t55","butter","egg","echine","quasi-de-veau","foie-de-volaille","pistachio","cognac","quatre-epices","curing-salt","black-pepper","shallot","gelatine-en-feuilles"],
techniques:["mariner","hacher","abaisser","foncer","farcir","dorer","pate-en-croute","gelee"],
wines:[{appellation:"Beaujolais-Villages, gamay",style:"light tannin, red fruit, marked acidity",band:2,why:{en:"Low tannin, because tannin binds with liver and turns metallic; the acidity cuts the cold fat of the forcemeat.",fr:"Tanin faible, car le tanin se lie au foie et vire métallique ; l'acidité coupe le gras froid de la farce."}},{appellation:"Côtes du Jura, chardonnay",style:"dry, white, oxidative notes, high acidity",band:3,why:{en:"Oxidative notes meet the cooked liver; the acidity lifts a filling that coats the palate.",fr:"Les notes oxydatives rencontrent le foie cuit ; l'acidité relève une farce qui tapisse le palais."}},{appellation:"Vouvray sec, chenin blanc",style:"dry, high acidity, firm structure",band:2,why:{en:"High acidity against the fat, and no oak or tannin to fight the jelly and the pastry.",fr:"Acidité élevée contre le gras, sans bois ni tanin qui contrarieraient la gelée et la pâte."}}]},

{id:"quenelles-de-brochet-sauce-nantua",group:"france",name:{en:"Pike quenelles, Nantua sauce",fr:"Quenelles de brochet sauce Nantua"},
region:{en:"Bugey and the Dombes ponds in the Ain; adopted by Lyon.",fr:"Bugey et étangs de la Dombes, dans l’Ain ; adoptées par Lyon."},era:{en:"Nineteenth century; the crayfish sauce takes its name from the town of Nantua.",fr:"XIXe siècle ; la sauce aux écrevisses tient son nom de la ville de Nantua."},
summary:{en:"Pike flesh is worked with a panade, egg and butter, shaped and poached, where it swells and sets. It is napped with Nantua sauce, a velouté enriched with crayfish butter and cream, and coloured under heat.",
fr:"La chair de brochet est travaillée avec une panade, des œufs et du beurre, façonnée puis pochée, où elle gonfle et prend. On la nappe de sauce Nantua, un velouté monté au beurre d'écrevisses et à la crème, puis on la fait colorer."},
balance:{en:"Pike is lean, bony and bland, which is precisely why it works here: the flesh is a protein scaffold, and the flavour is carried entirely by the fat and the shells. The panade holds water and the egg sets around it, so the quenelle swells in the poaching liquid and stays light instead of dense — a thickened starch is what makes a lean protein tender. The sauce then loads on crayfish butter and cream, so the construction is a bland, airy body against a very rich coating, and neither is edible alone. Acidity in the reduction and the tomato is the only thing keeping that coating from reading as flat.",
fr:"Le brochet est maigre, plein d'arêtes et neutre, et c'est exactement pour cela qu'il convient : la chair sert de charpente protéique, le goût vient entièrement de la matière grasse et des carapaces. La panade retient l'eau et l'œuf prend autour, si bien que la quenelle gonfle au pochage et reste légère au lieu de devenir compacte — c'est un amidon lié qui rend tendre une protéine maigre. La sauce apporte ensuite le beurre d'écrevisses et la crème : un corps neutre et aérien contre un nappage très riche, dont aucun ne se mange seul. L'acidité de la réduction et de la tomate est la seule chose qui empêche ce nappage de tomber à plat."},
ingredients:["pike","egg","butter","cream","flour-t55","crayfish","tomato","cognac","shallot","carrot","nutmeg","salt"],
techniques:["pate-a-choux","pocher","roux-blanc","mirepoix","reduction","passer-au-chinois","monter-au-beurre","gratiner"],
wines:[{appellation:"Côtes du Jura, Chardonnay",style:"Dry, moderate body, brisk acidity, restrained oak.",band:2,why:{en:"The acidity works against the crayfish butter and the cream in the sauce.",fr:"L'acidité travaille contre le beurre d'écrevisses et la crème de la sauce."}},{appellation:"Roussette de Savoie (Altesse)",style:"Dry, firm, low tannin, nutty on the finish.",band:2,why:{en:"No tannin, which would harden against the shellfish; the nutty finish meets the crayfish butter.",fr:"Pas de tanin, qui durcirait au contact du crustacé ; la finale de fruit sec rejoint le beurre d'écrevisses."}},{appellation:"Saint-Véran (Chardonnay)",style:"Dry, rounded, medium acidity.",band:2,why:{en:"Enough acidity to lift the fat without stripping a dish that carries little flavour of its own.",fr:"Assez d'acidité pour relever la graisse sans décaper un plat qui a peu de goût propre."}}]},

{id:"ramen-au-shoyu",group:"monde",name:{en:"Shoyu ramen",fr:"Ramen au shoyu"},
region:{en:"Tokyo, Japan",fr:"Tokyo, Japon"},era:{en:"1910",fr:"1910"},
summary:{en:"Alkaline wheat noodles in a stock built from poultry, kombu, dried shiitake and katsuobushi, seasoned by a soy-sauce base poured into the bowl first. The shop credited with it is Rairaiken, opened in Asakusa in 1910 with cooks brought from Yokohama's Chinatown.",
fr:"Des nouilles de blé alcalines dans un bouillon de volaille, kombu, shiitaké séché et katsuobushi, assaisonné par une base de sauce soja versée d'abord au fond du bol. La maison à laquelle on l'attribue est Rairaiken, ouverte à Asakusa en 1910 avec des cuisiniers venus du quartier chinois de Yokohama."},
balance:{en:"The bowl is assembled from three parts built separately: the tare, the soy base, carries the salt and the glutamate; the stock carries the body it gets from bone collagen and from the inosinate of the katsuobushi; the noodle carries the texture. Kansui, the alkaline salt, is what makes a noodle a ramen noodle — it modifies the gluten, yellows the dough and keeps it firm in scalding stock. A layer of fat floats on the surface, insulating the soup and carrying aroma upward. The rest of the bowl works by contrast: raw negi for pungency, menma for acidity and bite, the braised pork belly for fat.",
fr:"Le bol se monte en trois pièces construites séparément : le tare, la base de shoyu, porte le sel et le glutamate ; le bouillon porte le corps que lui donnent le collagène des os et l'inosinate du katsuobushi ; la nouille porte la texture. Le kansui, sel alcalin, est ce qui fait la nouille de ramen : il modifie le gluten, jaunit la pâte et la maintient ferme dans un bouillon brûlant. Une couche de gras flotte en surface, elle isole thermiquement la soupe et fait monter les arômes. Le reste du bol travaille par contraste : le negi cru pour le piquant, le menma pour l'acidité et le croquant, la poitrine de porc braisée pour le gras."},
ingredients:["flour-t55","kansui","chicken","pork-belly","kombu","dried-shiitake-donko","katsuobushi","koikuchi-shoyu","hon-mirin","egg","negi","menma","nori","garlic"],
techniques:["fond-blanc","depouiller","infusion-a-froid","mijoter","braiser","mariner","passer-au-chinois","bouillir"],
wines:[{appellation:"Saké junmai, Japon",style:"sec, acidité faible, riche en acides aminés",band:2,why:{en:"Low acidity, because the stock already carries salt and glutamate and an acidic drink would set against them.",fr:"Acidité faible, parce que le bouillon porte déjà le sel et le glutamate et qu'une boisson acide s'y opposerait."}},{appellation:"Muscadet Sèvre-et-Maine sur lie",style:"blanc sec, acidité élevée, salin, sans bois",band:1,why:{en:"Salinity and high acidity against the layer of pork fat sitting on the surface.",fr:"La salinité et l'acidité élevée face à la couche de gras de porc posée en surface."}},{appellation:"Mugicha, infusion d'orge grillée, sans alcool",style:"infusion torréfiée, sans sucre, sans acidité, servie froide",band:1,why:{en:"Roasted bitterness rinses the fat without adding acid or sugar to a bowl already high in salt.",fr:"L'amertume torréfiée rince le gras sans ajouter d'acide ni de sucre à un bol déjà très salé."}}]},

{id:"ratatouille",group:"france",name:{en:"Ratatouille",fr:"Ratatouille niçoise"},
region:{en:"Comté de Nice, Provence",fr:"Comté de Nice, Provence"},era:{en:"Peasant dish; the word is attested in 1778, the vegetable-by-vegetable method is twentieth century",fr:"Plat paysan ; le mot est attesté en 1778, la cuisson légume par légume est du XXe siècle"},
summary:{en:"Aubergine, courgette, pepper, tomato and onion cooked in olive oil and brought together. Everything turns on method: cooked together it becomes a stew, cooked separately and assembled it keeps each vegetable identifiable.",
fr:"Aubergine, courgette, poivron, tomate et oignon cuits à l'huile d'olive puis réunis. Tout se joue sur la méthode : cuits ensemble on obtient un ragoût, cuits séparément puis assemblés chaque légume reste identifiable."},
balance:{en:"Each vegetable releases its water at a different rate, which is why cooking them separately and combining at the end gives distinct pieces rather than a purée. Aubergine is a sponge: salted and drained first, it takes up less oil and holds its shape. Tomato supplies the acid and the liquid that becomes the sauce, while courgette and pepper supply sugar, so the seasoning problem is keeping enough acidity to carry them. Olive oil is not a cooking medium here but an ingredient, and the basil goes in raw at the end because its aroma does not survive heat.",
fr:"Chaque légume rend son eau à un rythme différent : c'est pourquoi les cuire séparément et les réunir à la fin donne un plat de morceaux distincts plutôt qu'une purée. L'aubergine est une éponge — dégorgée au sel, elle prend moins d'huile et garde sa tenue. La tomate fournit l'acide et le liquide qui deviendra la sauce ; la courgette et le poivron fournissent le sucre, et tout le problème d'assaisonnement consiste à garder assez d'acidité pour les porter. L'huile d'olive n'est pas ici un simple milieu de cuisson mais un ingrédient, et le basilic s'ajoute cru à la fin car son arôme ne survit pas à la chaleur."},
ingredients:["eggplant","zucchini","bell-pepper","tomato","onion","garlic","olive-oil","thyme","bay-leaf","basil"],
techniques:["degorger","emincer","monder","sauter","etuver","mijoter","chiffonnade"],
wines:[{appellation:"Côtes de Provence rosé",style:"dry rosé, low tannin, moderate acidity",band:2,why:{en:"Its acidity answers the tomato's, and no tannin is present to clash with the bitterness of the aubergine.",fr:"Son acidité répond à celle de la tomate, et aucun tanin ne heurte l'amertume de l'aubergine."}},{appellation:"Bandol rouge (mourvèdre)",style:"red, firm tannin, herbal register",band:3,why:{en:"Tannin binds the olive oil, and the herbal register meets the thyme and bay.",fr:"Le tanin se lie à l'huile d'olive, et le registre herbacé rejoint le thym et le laurier."}},{appellation:"Coteaux d'Aix-en-Provence rouge",style:"medium-bodied red, soft tannin",band:2,why:{en:"Soft tannin does not dominate a dish that contains no animal fat to absorb it.",fr:"Un tanin souple ne domine pas un plat sans graisse animale pour l'absorber."}}]},

{id:"rillettes-de-tours",group:"charcuterie",name:{en:"Rillettes de Tours",fr:"Rillettes de Tours"},
region:{en:"Touraine",fr:"Touraine"},era:{en:"Attested in Touraine from the late 15th century; the word rille appears in writing in 1480, and Rabelais names the preparation in 1546",fr:"Attestées en Touraine dès la fin du XVe siècle ; le mot rille apparaît par écrit en 1480, et Rabelais nomme la préparation en 1546"},
summary:{en:"Pork shoulder and belly cut into strips and cooked for hours in their own fat until the fibres separate, then shredded and set in the strained fat. The Touraine version is cooked uncovered, which browns the meat and dries it to a coarse, golden shred.",
fr:"Épaule et poitrine de porc taillées en lanières, cuites des heures dans leur propre graisse jusqu'à ce que les fibres se séparent, puis effilochées et prises dans la graisse passée. La version tourangelle cuit à découvert, ce qui colore la viande et la sèche en filaments grossiers et dorés."},
balance:{en:"Rillettes are a fat emulsion held by meat fibre, and the whole difficulty is the temperature: too high and the fat separates into a greasy layer, too low and the collagen never dissolves and the meat stays in lumps. Cooking uncovered lets water leave, which concentrates flavour and lets the meat colour — the covered pot version is paler, finer and fattier, and both are correct for their own place. Salt is high here for a reason beyond taste: it draws water out and holds the shred together, and the fat cap on top seals the jar from air. On the plate the balance is not inside the dish at all — it is the sourdough crust and the acidity of a cornichon or a mustard, without which the fat has nothing to push against.",
fr:"Les rillettes sont une émulsion de gras tenue par la fibre de viande, et toute la difficulté est la température : trop chaud, le gras se sépare en couche grasse ; trop doux, le collagène ne fond pas et la viande reste en morceaux. La cuisson à découvert laisse partir l'eau, ce qui concentre le goût et permet la coloration — la version à l'étouffée est plus pâle, plus fine et plus grasse, et chacune est juste chez elle. Le sel est élevé pour une raison qui dépasse le goût : il tire l'eau et lie l'effiloché, et la couche de graisse au-dessus isole le pot de l'air. Dans l'assiette, l'équilibre n'est pas dans le plat : c'est la croûte du pain au levain et l'acidité d'un cornichon ou d'une moutarde, sans quoi le gras n'a rien contre quoi s'appuyer."},
ingredients:["echine","poitrine-de-porc","panne-de-porc","fatback","garlic","thyme","bay-leaf","quatre-epices","black-pepper","salt"],
techniques:["parer","raidir","confire","mijoter","a-l-etouffee","refroidissement-rapide"],
wines:[{appellation:"Vouvray sec, chenin blanc",style:"dry white, high acidity, quince and chalk aroma",band:2,why:{en:"High acidity cuts a preparation that is more than half fat; same region as the dish, same acid register.",fr:"L'acidité élevée coupe une préparation plus qu'à moitié grasse ; même région que le plat, même registre d'acidité."}},{appellation:"Montlouis-sur-Loire, chenin blanc",style:"dry white, high acidity, sparkling or still",band:2,why:{en:"When sparkling, the carbon dioxide adds a mechanical scouring on top of the acidity, which fat resists otherwise.",fr:"En version pétillante, le gaz carbonique ajoute un décapage mécanique à l'acidité, à quoi le gras résiste autrement."}},{appellation:"Touraine, sauvignon blanc",style:"dry white, high acidity, herbaceous aroma",band:1,why:{en:"Acidity plus green aroma matches the role of the gherkin served alongside.",fr:"L'acidité et les notes végétales tiennent le rôle du cornichon servi à côté."}}]},

{id:"ris-de-veau-aux-morilles",group:"france",name:{en:"Veal sweetbreads with morels",fr:"Ris de veau aux morilles"},
region:{en:"Franche-Comté and the Jura; standard in the classical repertoire.",fr:"Franche-Comté et Jura ; classique du répertoire."},era:{en:"Twentieth century in this form; morels and vin jaune are a long-standing Jura pairing.",fr:"XXe siècle sous cette forme ; morilles et vin jaune sont un accord jurassien de longue date."},
summary:{en:"Sweetbreads are soaked, blanched, trimmed of membrane, then coloured in butter and finished in a cream sauce built on vin jaune and morels. The blanching stage is what makes the trimming and the searing possible.",
fr:"Les ris sont dégorgés, blanchis, parés de leurs membranes, puis colorés au beurre et terminés dans une sauce à la crème montée au vin jaune et aux morilles. C'est le blanchiment qui rend le parage et le saisissement possibles."},
balance:{en:"Sweetbread is soft, pale and mild, and cream with mushrooms is soft, pale and mild too, so the whole risk of this dish is softness on softness. The blanching firms the protein enough to take a crust, and that crust is the only textural contrast on the plate — skip it and nothing has edges. Morels bring the second correction: dried, they are bitter and meaty, and that bitterness works on cream the way acid works on butter. Vin jaune supplies the third, its oxidative and acidic character reaching through cream that would otherwise flatten everything it touches.",
fr:"Le ris est moelleux, pâle et doux, et une crème aux champignons l'est tout autant : le risque du plat est le moelleux sur le moelleux. Le blanchiment raffermit assez la protéine pour prendre une croûte, et cette croûte est le seul contraste de texture de l'assiette — supprimez-la et plus rien n'a d'arête. Les morilles apportent la deuxième correction : séchées, elles sont amères et carnées, et cette amertume agit sur la crème comme l'acidité agit sur le beurre. Le vin jaune fournit la troisième, son caractère oxydatif et acide traversant une crème qui, sinon, aplatirait tout ce qu'elle touche."},
ingredients:["ris-de-veau-noix","morel","cream","vin-jaune","butter","flour-t55","shallot","lemon","white-pepper","salt"],
techniques:["degorger","blanchir","parer","raidir","rissoler","deglacer","reduction","monter-au-beurre"],
wines:[{appellation:"Château-Chalon (Savagnin, vin jaune)",style:"Dry, oxidative, walnut and green apple, very high acidity.",band:4,why:{en:"The same wine as the sauce; the acidity holds the cream and the oxidative notes meet the dried morels.",fr:"Le même vin que la sauce ; l'acidité tient la crème et les notes oxydatives rejoignent les morilles sèches."}},{appellation:"Côtes du Jura, Savagnin",style:"Dry, oxidative, high acidity.",band:3,why:{en:"Oxidative character against the mushroom, acidity against the fat, in one wine.",fr:"Caractère oxydatif contre le champignon, acidité contre le gras, dans un seul vin."}},{appellation:"Arbois, Chardonnay",style:"Dry, medium body, brisk acidity, light oak.",band:2,why:{en:"Acidity cuts the cream where the dish's own acid content is close to nil.",fr:"L'acidité tranche la crème là où le plat n'en apporte presque aucune."}}]},

{id:"risotto-a-la-milanaise",group:"monde",name:{en:"Saffron risotto, Milanese style",fr:"Risotto à la milanaise"},
region:{en:"Milan, Lombardy",fr:"Milan, Lombardie"},era:{en:"19th century",fr:"XIXe siècle"},
summary:{en:"Short-grain rice cooked by successive additions of meat stock until the starch it releases becomes the sauce, coloured and scented with saffron. Bone marrow melted into the fat at the start is what separates it from any other risotto.",
fr:"Un riz rond cuit par mouillements successifs au bouillon de viande, jusqu'à ce que l'amidon qu'il libère devienne la sauce, coloré et parfumé au safran. La moelle fondue dans la matière grasse de départ est ce qui le distingue de tout autre risotto."},
balance:{en:"The dish holds together on starch: stirring abrades the grains, amylopectin passes into the stock and binds the fat into a sauce that owes nothing to a roux. Marrow and butter supply that fat, parmesan supplies salt and glutamate, and the saffron sits above both with a bitter, slightly medicinal edge that keeps the richness from going flat. The rice must stay firm at the centre — a grain cooked right through releases all its starch at once and the sauce turns to paste. Temperature is the last variable: the finishing butter and cheese go in off the heat, because above roughly 70 °C the fat separates out.",
fr:"Le plat tient par l'amidon : le brassage râpe les grains, l'amylopectine passe dans le bouillon et lie la matière grasse en une sauce qui ne doit rien à un roux. La moelle et le beurre apportent ce gras, le parmesan le sel et le glutamate, et le safran se pose au-dessus avec une amertume légèrement médicinale qui empêche la richesse de s'aplatir. Le riz doit rester ferme au cœur : un grain cuit à cœur libère tout son amidon d'un coup et la sauce tourne à la colle. La température est la dernière variable — le beurre et le fromage de finition se montent hors du feu, au-delà de 70 °C environ la matière grasse se sépare."},
ingredients:["carnaroli","saffron","bone-marrow","onion","butter","parmesan","beef"],
techniques:["etuver","deglacer","mijoter","fond-blanc","monter-au-beurre","infusion-a-froid"],
wines:[{appellation:"Franciacorta, Lombardie",style:"effervescent, brut, seconde fermentation en bouteille",band:3,why:{en:"Carbon dioxide and acidity strip the butter and cheese fat from the palate between mouthfuls.",fr:"Le gaz carbonique et l'acidité décapent le gras du beurre et du fromage entre deux bouchées."}},{appellation:"Lugana, turbiana",style:"blanc sec, corps moyen, acidité moyenne",band:2,why:{en:"Acidity offsets the starch-and-butter binding, and the low aromatic intensity leaves the saffron legible.",fr:"L'acidité contrebalance la liaison amidon-beurre, et la faible intensité aromatique laisse le safran lisible."}},{appellation:"Valtellina Superiore, nebbiolo",style:"rouge peu coloré, acidité élevée, tanin fin",band:3,why:{en:"High acidity cuts the marrow fat, and the tannin is fine enough not to mask the saffron.",fr:"L'acidité élevée coupe le gras de la moelle, et le tanin est assez fin pour ne pas masquer le safran."}}]},

{id:"saint-honore",group:"patisserie",name:{en:"Saint-Honoré",fr:"Saint-honoré"},
region:{en:"Paris",fr:"Paris"},era:{en:"Created around 1847 at Chiboust; puff-pastry base replaced the brioche around 1863",fr:"Créé vers 1847 chez Chiboust ; base feuilletée substituée à la brioche vers 1863"},
summary:{en:"A puff pastry disc bearing a crown of caramel-dipped choux buns, filled and piped with a cream lightened by meringue. It began as a brioche base and took its present form when puff pastry replaced it.",
fr:"Un disque de feuilletage portant une couronne de choux glacés au caramel, garni et poché d'une crème allégée à la meringue. Il est né sur une base briochée et a pris sa forme actuelle quand le feuilletage l'a remplacée."},
balance:{en:"Three textures are stacked deliberately: brittle caramel, hollow choux, flaky pastry, and only then the cream. Crème Chiboust is a pastry cream folded with Italian meringue, so it holds its shape without the weight of butter or the fat of whipped cream — the lightness is structural, not decorative. The caramel is cooked dark enough to be faintly bitter, which is what stops the assembly from reading as sugar on sugar. Assembly is late by necessity: caramel absorbs atmospheric moisture within a couple of hours and goes sticky, taking the crunch with it.",
fr:"Trois textures sont empilées volontairement : caramel cassant, chou creux, feuilletage, et seulement ensuite la crème. La crème Chiboust est une pâtissière collée à la meringue italienne : elle se tient sans le poids du beurre ni le gras d'une chantilly — la légèreté est structurelle, pas décorative. Le caramel est poussé assez foncé pour rester légèrement amer, ce qui empêche l'ensemble de n'être que du sucre sur du sucre. Le montage se fait tard par nécessité : le caramel reprend l'humidité de l'air en deux heures, devient collant et emporte le croquant."},
ingredients:["flour-t45","laminating-butter","flour-t55","butter","egg","sugar","cream","cornstarch","vanilla","gelatine-en-feuilles","salt"],
techniques:["detrempe","tourage","pate-a-choux","dorer","creme-patissiere","meringue-italienne","caramel-a-l-eau"],
wines:[{appellation:"Vin de paille du Jura, savagnin et chardonnay",style:"Liquoreux, acidité élevée, notes de noix et d'abricot séché",band:3,why:{en:"Passerillage concentrates sugar and acid together, so the wine meets the caramel without going flat. The nut notes align with the browning of the caramel.",fr:"Le passerillage concentre le sucre et l'acidité ensemble, donc le vin répond au caramel sans s'aplatir. Les notes de noix rejoignent la caramélisation."}},{appellation:"Champagne demi-sec",style:"Effervescent, dosage élevé, acidité soutenue",band:3,why:{en:"The carbonation lifts a filling that is already aerated by meringue, and the dosage prevents the caramel from making the wine taste sharp.",fr:"La bulle allège une garniture déjà aérée par la meringue, et le dosage empêche le caramel de faire paraître le vin acide."}},{appellation:"Muscat de Beaumes-de-Venise, muscat à petits grains",style:"Vin doux naturel, sucre élevé, aromatique, acidité modérée",band:2,why:{en:"The sugar level exceeds that of the choux and cream, which is the condition for the wine not to read dry; the low tannin avoids clashing with the egg in the cream.",fr:"Le niveau de sucre dépasse celui des choux et de la crème, condition pour que le vin ne paraisse pas sec ; le tanin faible évite le heurt avec l'œuf de la crème."}}]},

{id:"saucisson-brioche",group:"charcuterie",name:{en:"Sausage baked in brioche",fr:"Saucisson brioché"},
region:{en:"Lyon",fr:"Lyon"},era:{en:"Charcutier's preparation of the Lyonnais; spread through the bouchons and the mères lyonnaises in the 19th century",fr:"Préparation de charcutier lyonnais ; diffusée par les bouchons et les mères lyonnaises au XIXe siècle"},
summary:{en:"A poached Lyon cooking sausage, sometimes studded with pistachio or truffle, wrapped in brioche dough and baked, then sliced warm or cold. It is bread and charcuterie built as one object rather than served side by side.",
fr:"Un saucisson de Lyon à cuire poché, parfois pistaché ou truffé, enveloppé de pâte à brioche et cuit au four, puis tranché tiède ou froid. C'est le pain et la charcuterie construits en un seul objet plutôt que servis côte à côte."},
balance:{en:"The sausage is poached before it is wrapped, for a mechanical reason: raw, it would render fat into the dough and give a greasy, collapsed crumb, and it would still be raw when the brioche is done. Brioche is the right bread here because its own butter and egg match the fat of the sausage instead of fighting it, while the crumb stays light enough not to make the slice heavy. Dry the poached sausage and let it cool before wrapping — a wet surface steams the dough from inside and the two separate in the oven, leaving a hollow ring. Serve it with mustard, not because it is traditional but because the dish has no acidity of its own and needs a sharp element to keep the second slice as interesting as the first.",
fr:"Le saucisson est poché avant d'être enveloppé, pour une raison mécanique : cru, il rendrait son gras dans la pâte et donnerait une mie grasse et affaissée, et il serait encore cru quand la brioche est cuite. La brioche est le bon pain ici parce que son beurre et ses œufs répondent au gras du saucisson au lieu de le contrarier, tout en gardant une mie assez légère pour que la tranche ne pèse pas. On sèche le saucisson poché et on le laisse refroidir avant d'envelopper — une surface humide fait buée dans la pâte et les deux se séparent au four, laissant un anneau creux. On sert avec de la moutarde, non par tradition mais parce que le plat n'a aucune acidité propre et qu'il lui faut un élément vif pour que la deuxième tranche vaille la première."},
ingredients:["saucisson-de-lyon-a-cuire","flour-t45","butter","egg","yeast","sugar","salt","pistachio","truffle"],
techniques:["pocher","refroidissement-rapide","abaisser","chemiser","dorer"],
wines:[{appellation:"Brouilly, gamay",style:"light tannin, high acidity, red fruit",band:2,why:{en:"Acidity cuts the butter of the brioche and the fat of the sausage in the same mouthful.",fr:"L'acidité coupe le beurre de la brioche et le gras du saucisson dans la même bouchée."}},{appellation:"Coteaux du Lyonnais, gamay",style:"light red, low tannin, high acidity",band:1,why:{en:"Low tannin, so nothing dries a dish that is already rich in fat and starch.",fr:"Tanin faible : rien ne dessèche un plat déjà riche en gras et en amidon."}},{appellation:"Saint-Véran, chardonnay",style:"dry white, moderate acidity, unoaked",band:2,why:{en:"Its weight matches the brioche crumb; the acidity handles the rendered fat.",fr:"Sa matière répond à la mie de brioche ; l'acidité prend en charge le gras fondu."}}]},

{id:"socca",group:"monde",name:{en:"Socca",fr:"Socca"},
region:{en:"Nice",fr:"Nice"},era:{en:"Descended from Ligurian farinata; Nice street food since the nineteenth century",fr:"Descend de la farinata ligure ; cuisine de rue niçoise depuis le XIXe siècle"},
summary:{en:"A thin chickpea-flour pancake baked at very high heat in a wide copper pan and served in torn pieces. It is Nice street food, eaten standing and scalding, seasoned with nothing but pepper.",
fr:"Galette fine de farine de pois chiche cuite à très haute température dans un large plat de cuivre, servie en morceaux déchirés. C'est une nourriture de rue niçoise, mangée debout et brûlante, avec du poivre pour seul assaisonnement."},
balance:{en:"Chickpea flour sets without gluten or egg: the starch and the legume protein are enough to bind. The batter must stay very loose and rest so the flour hydrates fully; too thick and the centre stays pasty. Cooking is very hot, very short and comes from above, blistering and browning the surface while the inside stays soft, and that contrast between crisp edge and creamy middle is the entire point. Olive oil, used generously, fries the surface and carries the flavour of the legume, which is dull without it; pepper is the only seasoning that cuts through.",
fr:"La farine de pois chiche prend sans gluten ni œuf : l'amidon et la protéine de la légumineuse suffisent à lier. La pâte doit rester très liquide et reposer pour que la farine s'hydrate entièrement ; trop épaisse, le cœur reste pâteux. La cuisson est très chaude, très courte et venue du dessus : elle cloque et brunit la surface pendant que l'intérieur reste moelleux, et ce contraste entre bord croustillant et milieu crémeux est tout le sujet. L'huile d'olive, généreuse, frit la surface et porte le goût de la légumineuse, fade sans elle ; le poivre est le seul assaisonnement qui la tranche."},
ingredients:["chickpea-flour","olive-oil","salt","black-pepper"],
techniques:["vanner","rotir","gratiner"],
wines:[{appellation:"Côtes de Provence rosé",style:"dry rosé, low tannin, citrus acidity",band:2,why:{en:"The acidity cuts the olive oil absorbed by the batter.",fr:"L'acidité coupe l'huile d'olive absorbée par la galette."}},{appellation:"Bellet rosé (Nice, braquet)",style:"dry rosé, light body, moderate acidity",band:4,why:{en:"A light body and acidity against a flatbread served hot and oily.",fr:"Corps léger et acidité face à une galette servie chaude et huileuse."}}]},

{id:"sole-meuniere",group:"france",name:{en:"Sole meunière",fr:"Sole meunière"},
region:{en:"Normandy and Paris; sole from the Channel.",fr:"Normandie et Paris ; sole de la Manche."},era:{en:"Nineteenth century, fixed in Parisian restaurant kitchens.",fr:"XIXe siècle, fixée dans les cuisines des restaurants parisiens."},
summary:{en:"A whole sole is skinned, dusted in flour and cooked in clarified butter until the coating colours, then finished with fresh butter taken to hazelnut brown, lemon and parsley. Everything happens in one pan, in a few minutes, with no sauce made separately.",
fr:"Une sole entière est habillée, passée dans la farine et cuite au beurre clarifié jusqu'à ce que l'enrobage colore, puis nappée d'un beurre noisette monté à la minute, de citron et de persil. Tout se joue dans une seule poêle, en quelques minutes, sans sauce montée à part."},
balance:{en:"The flour does two jobs: it dries the surface so it can colour, and it thickens the butter slightly as it browns, so the fat clings to the fish instead of running onto the plate. Butter taken to noisette develops roasted, nutty notes from its milk solids, and that toasted fat is the thing that needs correcting; the lemon, added off the heat, does it. Sole is lean and firm, so fat is added rather than rendered out — the dish is a fat you build and an acid you use to hold it in check. The same three moves work on any lean white fish: flour, coloured fat, acid at the end.",
fr:"La farine fait deux choses : elle assèche la surface pour qu'elle puisse colorer, et elle lie légèrement le beurre qui brunit, si bien que la matière grasse nappe le poisson au lieu de couler dans l'assiette. Le beurre mené en noisette développe des notes torréfiées grâce à ses protéines de lait, et c'est cette graisse grillée qu'il faut corriger ; le citron, ajouté hors du feu, s'en charge. La sole est maigre et ferme : la graisse est apportée, jamais rendue — le plat est une graisse que l'on construit et une acidité qui la tient. Les trois mêmes gestes valent pour tout poisson blanc maigre : farine, graisse colorée, acidité en fin de cuisson."},
ingredients:["dover-sole","flour-t55","clarified-butter","beurre-de-baratte","lemon","parsley","fleur-de-sel-guerande","white-pepper"],
techniques:["habiller","ebarber","beurre-clarifie","sauter","arroser"],
wines:[{appellation:"Muscadet Sèvre-et-Maine sur lie (Melon de Bourgogne)",style:"Dry, high acidity, saline, no oak.",band:1,why:{en:"The acidity cuts the browned butter, and the absence of oak leaves the lean flesh unmasked.",fr:"L'acidité tranche le beurre noisette, et l'absence de bois laisse la chair maigre à découvert."}},{appellation:"Chablis (Chardonnay)",style:"Dry, taut, unoaked in its village form.",band:2,why:{en:"Acidity balances the added fat; no tannin, which would clash with the iodine of the fish.",fr:"L'acidité équilibre la graisse ajoutée ; pas de tanin, qui heurterait l'iode du poisson."}},{appellation:"Cidre de Normandie, brut",style:"Dry, sparkling, low in alcohol, malic acidity.",band:1,why:{en:"Carbonation and malic acidity clear the butter from the palate between mouthfuls.",fr:"Le gaz et l'acidité malique nettoient le beurre entre deux bouchées."}}]},

{id:"souffle-au-fromage",group:"france",name:{en:"Cheese soufflé",fr:"Soufflé au fromage"},
region:{en:"Paris and the classical French repertoire.",fr:"Paris et le répertoire classique français."},era:{en:"Soufflé technique from the eighteenth century, codified by Carême in the early nineteenth.",fr:"Technique du soufflé au XVIIIe siècle, codifiée par Carême au début du XIXe."},
summary:{en:"A thick roux-based base is bound with yolks and grated hard cheese, then lightened with beaten whites and baked in a buttered, floured mould. It rises because the air trapped in the whites expands and the egg protein sets around it.",
fr:"Une base épaisse à base de roux est liée aux jaunes et au fromage râpé, puis allégée aux blancs montés et cuite dans un moule beurré et fariné. Il monte parce que l'air emprisonné dans les blancs se dilate et que la protéine d'œuf prend autour."},
balance:{en:"Volume and flavour pull in opposite directions here, and the base is where that is settled: it must be thick and aggressively seasoned, because a third of its volume is about to be foam that carries no taste. Cheese brings fat and salt, and fat is what destroys foam, so the whites are folded in on a base that is already stiff enough to hold them. Nutmeg and pepper are not decoration — they compensate for the dilution, and a base that tastes correct before folding will taste weak after. The eating contrast is between a set, coloured crust and an interior barely held together.",
fr:"Volume et goût tirent ici en sens contraire, et c'est la base qui arbitre : elle doit être épaisse et assaisonnée franchement, puisqu'un tiers de son volume va devenir une mousse sans saveur. Le fromage apporte gras et sel, et c'est le gras qui détruit la mousse : les blancs sont donc incorporés à une base déjà assez ferme pour les tenir. Muscade et poivre ne sont pas décoratifs — ils compensent la dilution, et une base juste avant l'incorporation sera fade après. Le contraste en bouche oppose une croûte prise et colorée à un intérieur à peine tenu."},
ingredients:["comte","parmesan","egg","butter","flour-t55","cream","nutmeg","white-pepper","salt"],
techniques:["roux-blanc","vanner","liaison-a-l-oeuf","monter-les-blancs","chemiser","gratiner"],
wines:[{appellation:"Côtes du Jura, Savagnin (oxidative style)",style:"Dry, oxidative, walnut and curry aromas, high acidity.",band:3,why:{en:"Oxidative notes meet the cooked cheese, and the acidity works against the butter in the base.",fr:"Les notes oxydatives rejoignent le fromage cuit, et l'acidité travaille contre le beurre de la base."}},{appellation:"Champagne, brut",style:"Dry, sparkling, high acidity.",band:3,why:{en:"Carbonation and acidity cut through egg fat and cheese fat, which coat the palate.",fr:"Le gaz et l'acidité tranchent le gras de l'œuf et du fromage, qui tapissent le palais."}},{appellation:"Arbois, Chardonnay",style:"Dry, medium body, marked acidity.",band:2,why:{en:"Acidity balances the fat; the low tannin content leaves the egg protein untouched.",fr:"L'acidité équilibre la graisse ; l'absence de tanin laisse la protéine d'œuf tranquille."}}]},

{id:"spaghetti-alla-carbonara",group:"monde",name:{en:"Spaghetti alla carbonara",fr:"Spaghetti alla carbonara"},
region:{en:"Rome, Lazio",fr:"Rome, Latium"},era:{en:"Mid-20th century",fr:"Milieu du XXe siècle"},
summary:{en:"Pasta bound off the heat with egg yolk, rendered guanciale fat and grated pecorino, seasoned with black pepper. There is no cream: the sauce is an emulsion of egg and fat carried by starchy cooking water, and the first printed recipe dates from 1954.",
fr:"Des pâtes liées hors du feu au jaune d'œuf, à la graisse fondue du guanciale et au pecorino râpé, poivrées au moulin. Il n'y a pas de crème : la sauce est une émulsion d'œuf et de gras portée par l'eau de cuisson amidonnée, et la première recette imprimée date de 1954."},
balance:{en:"The sauce is an emulsion: the yolk brings lecithin, the guanciale brings melted fat, and the starchy pasta water is what holds the two together. Everything turns on temperature — yolk sets between roughly 65 and 70 °C and coagulates into lumps above it, so the binding is done off the fire in a warm bowl. Pecorino and cured pork already carry a great deal of salt, which is why the pasta water is salted lightly. There is no acid at all on the plate, only fat, salt and pepper: the glass is what supplies the acidity that is missing.",
fr:"La sauce est une émulsion : le jaune apporte les lécithines, le guanciale la graisse fondue, et l'eau de cuisson amidonnée fait le lien entre les deux. Tout se joue sur la température — le jaune prend entre 65 et 70 °C environ et coagule en grumeaux au-delà, on lie donc hors du feu dans un récipient tiède. Le pecorino et la charcuterie salent déjà beaucoup, c'est pourquoi l'eau des pâtes est peu salée. Il n'y a aucun acide dans l'assiette, seulement du gras, du sel et du poivre : c'est le verre qui apporte l'acidité qui manque."},
ingredients:["semola-rimacinata","guanciale","egg","pecorino","black-pepper","salt"],
techniques:["bouillir","rissoler","emulsion-chaude","liaison-a-l-oeuf"],
wines:[{appellation:"Frascati Superiore, malvasia et trebbiano",style:"blanc sec, acidité moyenne à élevée, peu aromatique",band:1,why:{en:"The dish contains no acid of its own; the wine supplies it against the egg-and-pork-fat emulsion.",fr:"Le plat ne contient aucun acide ; le vin l'apporte face à l'émulsion d'œuf et de gras de porc."}},{appellation:"Cesanese del Piglio, Latium",style:"rouge, tanin faible, acidité fruit rouge",band:2,why:{en:"Low tannin, because firm tannin dries a sauce already high in fat and salt.",fr:"Peu de tanin, parce qu'un tanin ferme dessèche une sauce déjà chargée en gras et en sel."}},{appellation:"Trebbiano d'Abruzzo",style:"blanc sec, acidité élevée, sans bois",band:1,why:{en:"Acidity and no oak: oak tannin would add astringency to a plate that carries salt and fat only.",fr:"De l'acidité et pas de bois : le tanin du fût ajouterait de l'astringence à une assiette qui ne porte que du sel et du gras."}}]},

{id:"tajine-d-agneau-aux-pruneaux",group:"monde",name:{en:"Lamb tagine with prunes",fr:"Tajine d'agneau aux pruneaux"},
region:{en:"Morocco",fr:"Maroc"},era:{en:"Medieval Berber cookware, sweet-savoury register of al-Andalus",fr:"Vaisselle berbère médiévale, registre sucré-salé d’al-Andalus"},
summary:{en:"Lamb shoulder braised slowly in an earthenware dish under a conical lid, with saffron, ginger and cinnamon, finished with prunes, honey, toasted almonds and sesame. The pot is Berber and old; the meat-and-dried-fruit register came with the Andalusi cooking tradition after 1492.",
fr:"Une épaule d'agneau braisée lentement dans un plat en terre sous un couvercle conique, au safran, au gingembre et à la cannelle, finie aux pruneaux, au miel, aux amandes grillées et au sésame. Le plat en terre est berbère et ancien ; le registre viande-fruits secs est venu avec la tradition andalouse après 1492."},
balance:{en:"The conical lid condenses the steam and returns it to the meat, so the braise runs on very little added liquid: the shoulder cooks in its own juices and the collagen breaks down into gelatin. The sugar of the prunes and honey works against the lamb fat and against the salt — it is a balance, not a dessert, and it only holds if the salt and the bitterness of the ras el-hanout stay at the same level. Saffron and ginger supply the bitterness and the heat that keep the reduced syrup from going flat. The toasted almonds and sesame are the only firm texture in a dish that is otherwise entirely soft.",
fr:"Le couvercle conique condense la vapeur et la renvoie sur la viande : on braise avec très peu de liquide ajouté, l'épaule cuit dans son propre jus et le collagène se défait en gélatine. Le sucre des pruneaux et du miel travaille contre le gras de l'agneau et contre le sel — c'est un équilibre, pas un dessert, et il ne tient que si le sel et l'amertume du ras el-hanout restent au même niveau. Le safran et le gingembre apportent l'amertume et le piquant qui empêchent le sirop de fin de cuisson de s'aplatir. Les amandes et le sésame grillés sont la seule texture ferme d'un plat par ailleurs entièrement fondant."},
ingredients:["epaule-agneau","onion","garlic","ginger","saffron","cinnamon","ras-el-hanout","honey","prune","almond","sesame","smen","cilantro","olive-oil"],
techniques:["rissoler","etuver","a-l-etouffee","mijoter","reduction","pocher-les-fruits"],
wines:[{appellation:"Guerrouane, Maroc : grenache, cinsault, carignan",style:"rouge, fruit mûr, tanin faible, alcool moyen à élevé",band:1,why:{en:"Ripe fruit and low tannin sit with the sugar of the prunes; high tannin turns bitter against sweetness.",fr:"Le fruit mûr et le tanin faible tiennent avec le sucre des pruneaux ; un tanin élevé devient amer face au sucré."}},{appellation:"Côtes du Rhône, grenache",style:"rouge, fruit mûr, tanin modéré",band:1,why:{en:"Moderate tannin holds against the lamb fat while the ripe fruit follows the honey rather than opposing it.",fr:"Le tanin modéré tient face au gras d'agneau tandis que le fruit mûr suit le miel au lieu de s'y opposer."}},{appellation:"Thé vert gunpowder à la menthe, sans alcool",style:"infusion tannique, sucrée, servie chaude, sans alcool",band:1,why:{en:"Tannin and heat scour fat, and the added sugar meets the sweetness of the braise instead of contrasting with it.",fr:"Le tanin et la chaleur décapent le gras, et le sucre ajouté rejoint le sucré du braisé au lieu de s'y opposer."}}]},

{id:"tarte-au-citron-meringuee",group:"patisserie",name:{en:"Lemon meringue tart",fr:"Tarte au citron meringuée"},
region:{en:"French pâtisserie, nationwide",fr:"Pâtisserie française, diffusion nationale"},era:{en:"19th century; lemon cream of 18th-century English origin, meringue set on top in the 19th",fr:"XIXe siècle ; crème au citron d’origine anglaise du XVIIIe, meringue posée dessus au XIXe"},
summary:{en:"A blind-baked sweet pastry case filled with a cooked lemon cream mounted with butter, covered with meringue and browned. The whole construction exists to hold a very acid filling in place.",
fr:"Un fond de pâte sucrée cuit à blanc, garni d'une crème au citron cuite puis montée au beurre, recouvert de meringue et coloré. Toute la construction sert à tenir en place une garniture très acide."},
balance:{en:"Lemon juice is around 5 to 6 percent acid, far more than the palate tolerates alone, so two things buffer it: the butter mounted into the cream at low temperature, and the sugar of the meringue above. Butter added below 45 degrees emulsifies rather than melts out, which is what gives the curd its coating texture and blunts the sharp edge of the acid. The meringue is not decoration but a sweet counterweight, and browning it adds bitterness from the caramelised surface so the top is not merely sugar. The pastry must be baked blind and sealed, since curd is wet and acid and will soften a raw base fast.",
fr:"Le jus de citron titre environ 5 à 6 % d'acide, bien au-delà de ce que le palais supporte seul : deux choses le tamponnent, le beurre monté dans la crème à basse température et le sucre de la meringue au-dessus. Un beurre incorporé sous 45 degrés émulsionne au lieu de fondre, ce qui donne au curd sa texture nappante et émousse l'arête de l'acide. La meringue n'est pas un décor mais un contrepoids sucré, et sa coloration apporte l'amertume de la surface caramélisée, pour que le dessus ne soit pas que du sucre. Le fond doit être cuit à blanc et imperméabilisé, car un curd humide et acide ramollit vite une pâte crue."},
ingredients:["lemon","egg","sugar","butter","flour-t55","almond-flour","icing-sugar","salt","cornstarch"],
techniques:["sabler","fraiser","abaisser","foncer","cuire-a-blanc","a-la-nappe","monter-au-beurre","meringue-italienne"],
wines:[{appellation:"Monbazillac, sémillon et sauvignon botrytisés",style:"Liquoreux, sucre élevé, acidité soutenue, notes d'agrume confit",band:2,why:{en:"The sugar must exceed that of the meringue, otherwise the lemon acidity makes the wine taste thin. Botrytis adds citrus-peel notes on the same axis as the filling.",fr:"Le sucre doit dépasser celui de la meringue, sans quoi l'acidité du citron fait paraître le vin maigre. Le botrytis apporte des notes d'écorce d'agrume sur le même axe que la garniture."}},{appellation:"Muscat de Rivesaltes, muscat d'Alexandrie",style:"Vin doux naturel, sucre élevé, aromatique, faible tanin",band:2,why:{en:"High sugar and no tannin: tannin plus lemon acidity reads metallic, so a fortified white is the safer structure here.",fr:"Sucre élevé et aucun tanin : tanin plus acidité citrique donne une sensation métallique, donc un blanc muté est ici la structure la plus sûre."}},{appellation:"Thé vert sencha du Japon",style:"Sans sucre, amertume végétale, faible astringence",band:1,why:{en:"With no sugar to match, the bitterness takes over the balancing role and the acid-versus-sugar confrontation is avoided altogether.",fr:"Sans sucre à opposer, l'amertume prend le rôle d'équilibrage et l'affrontement acide-sucre est évité."}}]},

{id:"tarte-tatin",group:"patisserie",name:{en:"Tarte Tatin",fr:"Tarte Tatin"},
region:{en:"Sologne, Loir-et-Cher",fr:"Sologne, Loir-et-Cher"},era:{en:"Late 19th century, known across the Sologne by 1903",fr:"Fin du XIXe siècle, connue dans toute la Sologne dès 1903"},
summary:{en:"Apples cooked slowly in butter and sugar until they caramelise, covered with pastry and baked, then turned out upside down. The dish is built around the caramel that forms under the fruit, not around the pastry.",
fr:"Des pommes confites longuement au beurre et au sucre jusqu'au caramel, recouvertes de pâte, cuites au four, puis démoulées à l'envers. Tout le plat est construit sur le caramel qui se forme sous le fruit, pas sur la pâte."},
balance:{en:"A dry caramel is bitter, and that bitterness is what keeps the tart from being merely sweet. The apple must be a variety that holds its shape and stays acid when cooked; a soft, low-acid apple collapses into purée and leaves the caramel unopposed. The butter in the caramel and the butter in the pastry both need cutting, which is the job of the fruit acidity and, at the table, of the crème fraîche. The pastry sits on top during baking and underneath on the plate, so it has to be crisp enough to survive contact with the syrup for the few minutes before service.",
fr:"Un caramel à sec est amer, et c'est cette amertume qui empêche la tarte d'être seulement sucrée. La pomme doit être une variété qui tient à la cuisson et reste acide ; une pomme molle et peu acide s'effondre en purée et laisse le caramel sans contrepartie. Le beurre du caramel et celui de la pâte demandent tous deux à être tranchés : c'est le rôle de l'acidité du fruit et, à table, de la crème fraîche. La pâte cuit sur le dessus et se retrouve dessous à l'assiette, donc elle doit être assez cuite pour résister quelques minutes au contact du sirop."},
ingredients:["reinette-grise-du-canada","pomme-chantecler","apple","beurre-de-baratte","sugar","flour-t55","egg","salt","vanilla","creme-fraiche","calvados"],
techniques:["caramel-a-sec","confire","sabler","fraiser","abaisser"],
wines:[{appellation:"Coteaux du Layon, chenin blanc",style:"Moelleux à liquoreux, acidité élevée, notes de coing et de fruit confit",band:2,why:{en:"The residual sugar has to reach the level of the caramel; below it, the wine reads thin and acid. The acidity of chenin dissolves the butter held in the cooked apple.",fr:"Le sucre résiduel doit atteindre le niveau du caramel ; en dessous, le vin paraît maigre et acide. L'acidité du chenin dissout le beurre retenu dans la pomme confite."}},{appellation:"Cidre de Cornouaille AOP",style:"Brut, tanins légers, mousse fine, acidité malique",band:1,why:{en:"The carbonation and the light tannin scour the butter from the palate between mouthfuls. The malic acidity is the same acid the apple in the tart supplies.",fr:"Le gaz et le tanin léger raclent le beurre entre deux bouchées. L'acide malique est celui que la pomme apporte déjà dans la tarte."}},{appellation:"Pommeau de Normandie AOC",style:"Muté au calvados, sucré, oxydatif, notes de pomme cuite",band:2,why:{en:"The mutage leaves sugar at the level of the caramel while the eau-de-vie base carries the same fruit as the tart, so no second aroma is introduced.",fr:"Le mutage laisse un sucre au niveau du caramel, et l'eau-de-vie de base porte le même fruit que la tarte : aucun second arôme n'est introduit."}}]},

{id:"tartiflette",group:"france",name:{en:"Tartiflette",fr:"Tartiflette"},
region:{en:"Savoie and Haute-Savoie",fr:"Savoie et Haute-Savoie"},era:{en:"1980s, built on the older pela of the Aravis valley",fr:"Années 1980, bâtie sur la pela, plus ancienne, du val d’Aravis"},
summary:{en:"A gratin of potato, smoked belly and onion, topped with a whole reblochon split through its thickness. It dates from the 1980s and reworks the older Savoyard péla; the washed rind of the cheese is what carries it.",
fr:"Gratin de pommes de terre, lard et oignons, coiffé d'un reblochon fendu dans l'épaisseur. Le plat date des années 1980 et reprend la péla savoyarde ; c'est la croûte lavée du fromage qui le porte."},
balance:{en:"The washed rind of the reblochon melts into a sauce whose lactic edge is the only acidity in the dish; without it the potato-cream-bacon mass would read flat. The smoked belly brings salt and a roasted note, and the onions are cooked down to sweetness so the smoke has something to meet. Potato is the neutral carrier: it absorbs cream and rendered fat while adding nothing to the flavour. The gratin crust is a texture device — a dry, chewy top over a wet interior, so the mouth is not given one uniform soft mass.",
fr:"La croûte lavée du reblochon fond en une sauce dont la pointe lactique est la seule acidité du plat ; sans elle, l'ensemble pomme de terre, crème et lard resterait plat. La poitrine fumée apporte le sel et une note torréfiée, et les oignons sont fondus jusqu'au sucre pour que le fumé ait un contrepoint. La pomme de terre est le support neutre : elle absorbe la crème et la graisse rendue sans rien ajouter au goût. La croûte du gratin est un outil de texture — un dessus sec et mâchu sur un intérieur humide, pour que la bouche ne reçoive pas une masse molle uniforme."},
ingredients:["bintje-potato","reblochon","poitrine-fumee","onion","creme-fraiche","butter","garlic","black-pepper"],
techniques:["bouillir","emincer","rissoler","deglacer","gratiner"],
wines:[{appellation:"Roussette de Savoie (altesse)",style:"dry white, full-bodied, low aromatic intensity",band:2,why:{en:"The body matches the cream and cheese, and the acidity dissolves the rendered pork fat.",fr:"La matière répond à la crème et au fromage, et l'acidité dissout le gras de porc fondu."}},{appellation:"Vin de Savoie Apremont (jacquère)",style:"dry white, light, high acidity, slight spritz",band:1,why:{en:"High acidity and a light body scour a dish in which every element is fat.",fr:"Acidité haute et corps léger décapent un plat dont tous les éléments sont gras."}},{appellation:"Mondeuse (Savoie)",style:"red, firm tannin, peppery",band:2,why:{en:"Tannin binds the protein and fat of the melted cheese, and the peppery note meets the smoke of the belly.",fr:"Le tanin se lie à la protéine et au gras du fromage fondu, et la note poivrée rejoint le fumé du lard."}}]},

{id:"terrine-de-campagne",group:"charcuterie",name:{en:"Country terrine",fr:"Terrine de campagne"},
region:{en:"Widespread in France; farm charcuterie of the pig-killing season",fr:"Toute la France ; charcuterie de ferme du temps du tue-cochon"},era:{en:"Rural household preparation, codified as a restaurant standard in the 19th century",fr:"Préparation ménagère rurale, codifiée comme classique de restaurant au XIXe siècle"},
summary:{en:"Coarsely chopped pork shoulder, belly and liver, seasoned, packed into a lined mould and cooked slowly, then pressed and rested. It is the plainest test of forcemeat seasoning, since nothing in it hides a mistake.",
fr:"Épaule, poitrine et foie de porc hachés gros, assaisonnés, tassés dans une terrine chemisée et cuits doucement, puis pressés et reposés. C'est l'épreuve la plus nue de l'assaisonnement d'une farce : rien n'y cache une erreur."},
balance:{en:"The whole construction rests on one ratio: roughly a third fat to two thirds lean, below which the terrine goes dry and grainy in the fridge. Liver is the counterweight — its bitterness and its iron keep the fat from tasting like nothing, and past about a fifth of the total it takes over and turns the terrine chalky. Salt is measured on the weight of the meat, not by eye, at around sixteen grams per kilo, because a terrine that is under-salted cannot be corrected once cooked. Rest is the last variable: two days in the cold let salt and spice move through the mass, and the crépine and the pressing hold the slice together so it cuts instead of collapsing.",
fr:"Toute la construction tient à un rapport : environ un tiers de gras pour deux tiers de maigre, en dessous duquel la terrine devient sèche et granuleuse au froid. Le foie est le contrepoids — son amertume et son fer empêchent le gras de ne rien goûter, et au-delà d'un cinquième du total il prend le dessus et rend la terrine crayeuse. Le sel se pèse sur le poids de viande, pas à l'œil, autour de seize grammes au kilo : une terrine sous-salée ne se rattrape pas après cuisson. Le repos est la dernière variable : deux jours au froid laissent le sel et les épices diffuser dans la masse, et la crépine puis le pressage tiennent la tranche, qui se coupe au lieu de s'effondrer."},
ingredients:["echine","poitrine-de-porc","foie-de-porc","caul-fat","shallot","garlic","thyme","bay-leaf","juniper","cognac","egg","curing-salt","black-pepper"],
techniques:["hacher","ciseler","mariner","chemiser","terrine","refroidissement-rapide"],
wines:[{appellation:"Chinon, cabernet franc",style:"dry red, moderate tannin, green-herb and red-fruit aroma",band:2,why:{en:"Moderate tannin holds against the fat without gripping the liver; the acidity clears the palate between slices.",fr:"Un tanin modéré tient contre le gras sans accrocher le foie ; l'acidité nettoie le palais entre deux tranches."}},{appellation:"Beaujolais, gamay",style:"light tannin, high acidity, red fruit",band:1,why:{en:"Acidity does the work the cornichon does on the plate: it cuts the fat and resets the palate.",fr:"L'acidité fait le travail du cornichon dans l'assiette : elle coupe le gras et remet le palais à zéro."}},{appellation:"Alsace, pinot gris",style:"dry to off-dry white, low acidity, full body",band:2,why:{en:"Body matches the density of the forcemeat; any residual sugar offsets the salt of the cure.",fr:"Le gras du vin répond à la densité de la farce ; le sucre résiduel compense le sel de la salaison."}}]},

{id:"terrine-de-foie-gras",group:"charcuterie",name:{en:"Foie gras terrine",fr:"Terrine de foie gras"},
region:{en:"Périgord, Gascogne, Alsace",fr:"Périgord, Gascogne, Alsace"},era:{en:"Fattened-liver cookery is ancient; the moulded terrine belongs to 19th-century French charcuterie",fr:"La cuisine du foie gras est très ancienne ; la terrine moulée relève de la charcuterie française du XIXe siècle"},
summary:{en:"A deveined duck or goose liver seasoned, marinated, packed into a terrine and cooked at low temperature, then pressed and matured for several days. Almost nothing is done to it, which is why every parameter is a temperature.",
fr:"Un foie de canard ou d'oie déveiné, assaisonné, mariné, tassé en terrine et cuit à basse température, puis pressé et affiné plusieurs jours. On ne lui fait presque rien : c'est pourquoi chaque paramètre est une température."},
balance:{en:"Foie gras is around half fat, and that fat melts between about 35 and 45 degrees, so the cooking window is narrow: too hot and the terrine renders into a shrunken block sitting in grease, too cool and the texture stays raw and pasty. Bring the liver to room temperature before deveining, because a cold liver tears and a warm one is soft enough to open along the veins with the thumb. Seasoning is weighed — roughly twelve grams of salt and two of sugar per kilo — and the sugar is not for sweetness but to round the salt and hold colour. Everything served against it exists to cut: an acid or bitter garnish, and a bread with enough crust to give a dish with no texture of its own something to work against.",
fr:"Le foie gras est gras à environ la moitié, et ce gras fond entre trente-cinq et quarante-cinq degrés : la fenêtre de cuisson est donc étroite — trop chaud, la terrine fond en un bloc rétracté baignant dans la graisse ; trop tiède, la texture reste crue et pâteuse. On tempère le foie avant de le déveiner, car un foie froid se déchire quand un foie tempéré s'ouvre au pouce le long des veines. L'assaisonnement se pèse — environ douze grammes de sel et deux de sucre au kilo — et le sucre n'est pas là pour sucrer mais pour arrondir le sel et tenir la couleur. Tout ce qu'on sert à côté existe pour couper : une garniture acide ou amère, et un pain assez croûté pour donner de la matière à un plat qui n'en a aucune."},
ingredients:["foie-gras","salt","white-pepper","sugar","curing-salt","armagnac","vin-de-paille","quatre-epices","fleur-de-sel-guerande"],
techniques:["denerver","mariner","foie-gras-en-terrine","basse-temperature","terrine","refroidissement-rapide"],
wines:[{appellation:"Jurançon moelleux, petit manseng",style:"sweet white, high acidity, citrus and stone-fruit aroma",band:3,why:{en:"Sugar offsets the salt of the cure, and the acidity underneath stops the sweetness from adding to the fat already coating the palate.",fr:"Le sucre compense le sel de la salaison, et l'acidité en dessous empêche le sucré de s'ajouter au gras qui tapisse déjà le palais."}},{appellation:"Coteaux du Layon, chenin blanc",style:"sweet white, high acidity, botrytised",band:3,why:{en:"High acidity for the fat, residual sugar for the salt; two axes at once, which a dry wine cannot do here.",fr:"L'acidité pour le gras, le sucre résiduel pour le sel ; deux axes à la fois, ce qu'un vin sec ne fait pas ici."}},{appellation:"Côtes du Jura, savagnin",style:"dry white, oxidative, high acidity, nutty aroma",band:4,why:{en:"The dry alternative: oxidative notes meet the cooked liver, and the acidity cuts without adding sugar to a rich dish.",fr:"L'option sèche : les notes oxydatives rencontrent le foie cuit, et l'acidité coupe sans ajouter de sucre à un plat riche."}},{appellation:"Monbazillac, sémillon and sauvignon",style:"sweet white, botrytised, moderate acidity",band:2,why:{en:"Residual sugar answers the salt; the botrytis bitterness gives an edge the liver lacks.",fr:"Le sucre résiduel répond au sel ; l'amertume de botrytis donne l'arête qui manque au foie."}}]},

{id:"tournedos-rossini",group:"france",name:{en:"Tournedos Rossini",fr:"Tournedos Rossini"},
region:{en:"Paris, restaurant cooking of the Second Empire.",fr:"Paris, cuisine de restaurant du Second Empire."},era:{en:"1850s–1860s, attributed to the Café Anglais and to the Maison Dorée; named for the composer Rossini.",fr:"Années 1850-1860, attribué au Café Anglais et à la Maison Dorée ; nommé d’après le compositeur Rossini."},
summary:{en:"A thick round of beef fillet is seared in butter, topped with a slice of foie gras coloured at the last moment, and covered with black truffle and a Madeira-based sauce. It is served on a fried crouton that keeps the meat out of the sauce.",
fr:"Un tournedos de filet de bœuf est saisi au beurre, coiffé d'une escalope de foie gras colorée à la minute, puis couvert de lames de truffe noire et d'une sauce au madère. Il est dressé sur un croûton frit qui isole la viande de la sauce."},
balance:{en:"This is a construction with almost no acidity in it, which is what makes it hard: fillet is lean but bland, foie gras is close to pure fat, truffle is aroma without weight, and the sauce is the only element that can push back. That is why the Madeira is reduced rather than added raw — reduction concentrates its acidity and its residual sugar together, and both are needed against the liver. The crouton is structural, not decorative: it absorbs the sauce and gives the one crisp texture in a plate that is otherwise entirely soft. Portions stay small for the same reason a rich sauce stays thin — the palate saturates fast when nothing cuts.",
fr:"C'est une construction presque sans acidité, et c'est là sa difficulté : le filet est maigre mais neutre, le foie gras est quasi pur gras, la truffe est un arôme sans masse, et la sauce est le seul élément capable de répondre. D'où le madère réduit et non ajouté cru — la réduction concentre ensemble son acidité et son sucre résiduel, et le foie a besoin des deux. Le croûton est structurel et non décoratif : il absorbe la sauce et donne la seule texture croustillante d'une assiette autrement entièrement moelleuse. Les portions restent petites pour la même raison qu'une sauce riche reste courte — le palais sature vite quand rien ne tranche."},
ingredients:["tenderloin","foie-gras","truffle","truffle-juice","madeira-sercial","butter","clarified-butter","black-pepper","salt"],
techniques:["parer","ficeler","saisir","deglacer","fond-brun","reduction","glace-de-viande","monter-au-beurre"],
wines:[{appellation:"Pomerol (Merlot dominant)",style:"Full body, ripe tannin, moderate acidity.",band:4,why:{en:"Tannin binds to the protein and fat of the fillet and the liver, which softens its grip.",fr:"Le tanin se lie à la protéine et au gras du filet et du foie, ce qui adoucit sa prise."}},{appellation:"Hermitage rouge (Syrah)",style:"Firm tannin, dense, notes of black fruit and pepper.",band:4,why:{en:"Firm tannin against a dish with no acidity of its own; the structure comes from the wine.",fr:"Un tanin ferme face à un plat sans acidité propre ; la structure vient du vin."}},{appellation:"Madeira, Sercial",style:"Dry, oxidative, high acidity, fortified.",band:3,why:{en:"The same wine as the sauce; its acidity is what cuts the foie gras fat.",fr:"Le même vin que la sauce ; c'est son acidité qui tranche le gras du foie gras."}}]},

{id:"tete-de-veau-sauce-gribiche",group:"charcuterie",name:{en:"Calf's head with sauce gribiche",fr:"Tête de veau sauce gribiche"},
region:{en:"Paris and Lyon; old Parisian kitchen stock according to Prosper Montagné",fr:"Paris et Lyon ; fonds de cuisine parisienne ancienne selon Prosper Montagné"},era:{en:"The cut is old; the pairing with gribiche is recorded from 1924 and becomes a standard from the 1950s",fr:"Le morceau est ancien ; l’accord avec la gribiche est attesté dès 1924 et devient un classique à partir des années 1950"},
summary:{en:"Boned calf's head, soaked and rolled, poached slowly in an acidulated broth until gelatinous, served warm with a cold emulsified sauce of hard-boiled yolk, mustard, capers, gherkins and herbs. Gribiche is not a mayonnaise: its base is cooked yolk, which gives a thicker, grainier sauce.",
fr:"Tête de veau désossée, dégorgée et roulée, pochée doucement dans un blanc acidulé jusqu'à devenir gélatineuse, servie tiède avec une sauce froide montée sur jaune dur, moutarde, câpres, cornichons et herbes. La gribiche n'est pas une mayonnaise : sa base est le jaune cuit, ce qui donne une sauce plus épaisse et plus granuleuse."},
balance:{en:"The head is almost pure collagen and fat: poached long enough it becomes soft, sticky and completely without edge, which is exactly why it cannot be served alone. Gribiche supplies every missing axis at once — acid from vinegar and gherkin, salt from the capers, bitterness from the herbs, and a granular texture against flesh that has none. Cooking the head in a blanc, water with flour and lemon or vinegar, keeps it pale and stops the acidity of the sauce arriving as a surprise at the end. Serve the meat warm and the sauce cold: the temperature gap is part of the construction, and a warmed gribiche both splits and loses the sharpness the dish is built on.",
fr:"La tête est presque uniquement du collagène et du gras : pochée assez longtemps, elle devient molle, collante et totalement sans arête, ce qui est précisément pourquoi elle ne peut pas se servir seule. La gribiche fournit d'un coup tous les axes manquants — l'acide du vinaigre et du cornichon, le sel des câpres, l'amertume des herbes, et une texture granuleuse contre une chair qui n'en a aucune. La cuisson dans un blanc, eau farinée et citronnée ou vinaigrée, garde la tête pâle et évite que l'acidité de la sauce n'arrive comme une surprise à la fin. On sert la viande tiède et la sauce froide : l'écart de température fait partie de la construction, et une gribiche réchauffée se rompt et perd la vivacité sur laquelle tout repose."},
ingredients:["tete-de-veau","pied-de-veau","egg","dijon-mustard","cornichon","capers","parsley","tarragon","chervil","chives","sunflower-oil","white-wine-vinegar","carrot","onion"],
techniques:["degorger","blanchir","ficeler","pocher","mijoter","hacher","ciseler","emulsion-froide"],
wines:[{appellation:"Sancerre, sauvignon blanc",style:"dry white, high acidity, herbaceous and mineral",band:3,why:{en:"Its acidity sits at the level of the sauce, so the vinegar does not strip it; the herbaceous aroma tracks the chopped herbs.",fr:"Son acidité se place au niveau de la sauce, que le vinaigre ne décape donc pas ; les notes végétales suivent les herbes hachées."}},{appellation:"Bourgogne Aligoté",style:"dry white, high acidity, lean",band:1,why:{en:"High acidity is the only way a wine survives a vinegar-based sauce; the leanness contrasts the gelatin.",fr:"Une acidité élevée est la seule façon pour un vin de survivre à une sauce vinaigrée ; sa maigreur contraste avec la gélatine."}},{appellation:"Muscadet Sèvre et Maine sur lie, melon de Bourgogne",style:"dry white, high acidity, saline, light body",band:1,why:{en:"No tannin and no oak, so nothing adds dryness to a dish already coated in collagen.",fr:"Ni tanin ni bois : rien n'ajoute de sécheresse à un plat déjà tapissé de collagène."}}]},

{id:"oeuf-en-gelee",group:"charcuterie",name:{en:"Egg in aspic",fr:"Œuf en gelée"},
region:{en:"Paris, the charcutier-traiteur and bistro trade",fr:"Paris, charcuterie-traiteur et bistrot"},era:{en:"Aspic is medieval, recorded in the Viandier around 1375; the egg, ham and tarragon version fixes in the 1930s",fr:"La gelée est médiévale, notée dans le Viandier vers 1375 ; la version œuf, jambon et estragon se fixe dans les années 1930"},
summary:{en:"A soft-boiled egg set in clarified, Madeira-scented jelly over a slice of cooked ham and a tarragon leaf, turned out of an oval mould. Every element is bland on its own, so the jelly carries all the seasoning.",
fr:"Un œuf mollet pris dans une gelée clarifiée au madère, sur une tranche de jambon blanc et une feuille d'estragon, démoulé d'un petit moule ovale. Chaque élément est fade isolément : c'est la gelée qui porte tout l'assaisonnement."},
balance:{en:"The runny yolk is the fat of this dish, and it is the only fat, so the jelly has to be seasoned hard — salted, peppered, and cut with Madeira or a spoon of vinegar, or the whole thing tastes of cold water. Clarification is not cosmetic: a cloudy jelly is a jelly that boiled, and boiling both clouds it and cooks out the aromatics that make it worth eating. The gelatin ratio decides the texture — enough to unmould cleanly, no more, because a firm jelly against a soft yolk is the wrong contrast; you want the jelly to yield first. Chill in stages, setting a thin layer before the egg goes in, so nothing floats and the tarragon stays where it was placed.",
fr:"Le jaune coulant est le gras de ce plat, et c'est le seul : la gelée doit donc être assaisonnée franchement — salée, poivrée, relevée au madère ou d'une cuillerée de vinaigre, sans quoi l'ensemble goûte l'eau froide. La clarification n'est pas cosmétique : une gelée trouble est une gelée qui a bouilli, et l'ébullition trouble autant qu'elle chasse les aromates qui justifient le plat. Le dosage de gélatine décide de la texture — juste de quoi démouler proprement, pas plus, car une gelée ferme contre un jaune coulant est le mauvais contraste ; c'est la gelée qui doit céder la première. On refroidit par étapes, en faisant prendre un fond mince avant de poser l'œuf, pour que rien ne flotte et que l'estragon reste où on l'a mis."},
ingredients:["egg","jambon-de-paris","tarragon","gelatine-en-feuilles","madeira-sercial","poule-a-bouillir","carrot","leek","black-pepper"],
techniques:["fond-blanc","clarifier","pocher","chemiser","aspic","gelee","refroidissement-rapide"],
wines:[{appellation:"Chablis, chardonnay",style:"dry white, high acidity, unoaked, mineral",band:3,why:{en:"Unoaked and lean, so it does not cover a dish whose flavours are quiet; the acidity handles the yolk.",fr:"Sans bois et tendu, il ne recouvre pas un plat aux saveurs discrètes ; l'acidité prend le jaune en charge."}},{appellation:"Champagne blanc de blancs",style:"dry sparkling, high acidity, chardonnay only",band:4,why:{en:"Carbonation and acidity clear the coating left by the yolk; no tannin to react with the gelatin.",fr:"Le gaz et l'acidité nettoient le film laissé par le jaune ; aucun tanin ne réagit avec la gélatine."}},{appellation:"Sencha, Japanese green tea, served cold",style:"non-alcoholic, low tannin when brewed cool, vegetal and saline",band:1,why:{en:"Brewed cool it stays low in tannin, which would otherwise dry the gelatin; its vegetal note tracks the tarragon.",fr:"Infusé à basse température, il reste pauvre en tanin, qui dessécherait la gélatine ; sa note végétale suit l'estragon."}}]},

{id:"oeufs-en-meurette",group:"france",name:{en:"Poached eggs in red wine sauce",fr:"Œufs en meurette"},
region:{en:"Bourgogne, around Dijon and Beaune.",fr:"Bourgogne, autour de Dijon et de Beaune."},era:{en:"Nineteenth century, from the wine-growers' kitchens; the sauce is borrowed from bœuf bourguignon.",fr:"XIXe siècle, issu des cuisines de vignerons ; la sauce est empruntée au bœuf bourguignon."},
summary:{en:"Eggs are poached in acidulated water and served on a reduced red wine sauce garnished with smoked pork belly, glazed pearl onions and mushrooms. The sauce is a meurette, the same reduction that dresses a bourguignon.",
fr:"Les œufs sont pochés à l'eau vinaigrée et servis sur une sauce au vin rouge réduite, garnie de lardons fumés, de petits oignons glacés et de champignons. La sauce est une meurette, la même réduction qui accompagne un bourguignon."},
balance:{en:"A reduced red wine is acidic and astringent, and reduction concentrates both, so the sauce cannot stand without fat: butter mounted at the end and the rendered pork are what round it off. The yolk is the second correction and the real point of the dish — broken at the table, it thickens the sauce in the plate, so the liaison happens after service rather than in the pan. Glazed onions add sugar against the wine's acidity, and the smoked pork adds salt against its astringency. Read the plate as three counterweights to one aggressive reduction, and you can rebuild it with any poached protein.",
fr:"Un vin rouge réduit est acide et astringent, et la réduction concentre les deux : la sauce ne tient pas sans gras, et ce sont le beurre monté en fin et le lard fondu qui l'arrondissent. Le jaune est la seconde correction et le véritable propos du plat — crevé à table, il lie la sauce dans l'assiette, la liaison se faisant après le service et non dans la casserole. Les oignons glacés apportent du sucre contre l'acidité du vin, le lard fumé du sel contre son astringence. Lisez l'assiette comme trois contrepoids à une réduction agressive, et vous la reconstruisez avec n'importe quelle protéine pochée."},
ingredients:["egg","poitrine-fumee","pearl-onion","field-mushroom","butter","flour-t55","shallot","garlic","thyme","bay-leaf","red-wine-vinegar","black-pepper","parsley"],
techniques:["pocher","rissoler","glacer-a-brun","reduction","beurre-manie","deglacer","passer-au-chinois"],
wines:[{appellation:"Bourgogne rouge (Pinot Noir)",style:"Light tannin, red fruit, high acidity.",band:2,why:{en:"Same grape as the reduction in the sauce; the light tannin is rounded by the yolk fat.",fr:"Même cépage que la réduction de la sauce ; le tanin léger est arrondi par le gras du jaune."}},{appellation:"Marsannay rouge (Pinot Noir)",style:"Firm acidity, fine tannin, red fruit.",band:3,why:{en:"Acidity matches the acidity already concentrated in the reduction, so neither element sharpens the other.",fr:"L'acidité répond à celle déjà concentrée dans la réduction, sans que l'une n'aiguise l'autre."}},{appellation:"Hautes-Côtes de Beaune rouge (Pinot Noir)",style:"Light body, low tannin, marked acidity.",band:2,why:{en:"Low tannin, because tannin binds to the egg protein and turns dry.",fr:"Peu de tanin, car le tanin se lie à la protéine de l'œuf et se dessèche."}}]}
];
